insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('small-wins-evening-notebook-page', 'Small Wins Evening Notebook Page', 'worksheet'::resource_kind, 'A nightly page for jotting down three small things that went acceptably, however ordinary.', 'Use it to help a client notice ordinary moments that went well.', array['Adults']::text[], 'Five minutes nightly for a week', 'Ask the client to write three small, concrete things each night, such as answering a call or making the bed. Read the page together at the next session and ask what they notice about which wins come easily. Keep it modest; if every entry feels forced, shrink the bar rather than the client.', '[{"id": "f0", "type": "textarea", "label": "Today''s date and how the day felt overall"}, {"id": "f1", "type": "textarea", "label": "First small thing that went acceptably"}, {"id": "f2", "type": "textarea", "label": "Second small thing that went acceptably"}, {"id": "f3", "type": "textarea", "label": "Third small thing that went acceptably"}, {"id": "f4", "type": "textarea", "label": "What I did to make one of them happen"}, {"id": "f5", "type": "textarea", "label": "What I want to carry into tomorrow"}]'::jsonb, array['self-monitoring', 'strengths', 'routines']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('values-based-decision-grid', 'Values-Based Decision Grid', 'worksheet'::resource_kind, 'A two-column grid for weighing a decision by what each choice offers and what it asks of the client.', 'Use it to help a client slow down a big choice and check it against what matters to them.', array['Adults', 'Teens']::text[], '25 minutes', 'Work through one real decision in session so the client sees how to use the grid alone. Ask the client to name the values behind each column in their own words. The grid sorts information; the decision stays with the client, and you can note when a choice feels pressured by someone else.', '[{"id": "f0", "type": "textarea", "label": "The decision I am facing"}, {"id": "f1", "type": "textarea", "label": "Choice A and what it offers me"}, {"id": "f2", "type": "textarea", "label": "Choice A and what it asks of me"}, {"id": "f3", "type": "textarea", "label": "Choice B and what it offers me"}, {"id": "f4", "type": "textarea", "label": "Choice B and what it asks of me"}, {"id": "f5", "type": "textarea", "label": "Which values each choice serves"}, {"id": "f6", "type": "textarea", "label": "What I need to find out before I decide"}]'::jsonb, array['values', 'planning', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('compassionate-letter-outline', 'Compassionate Letter Outline', 'worksheet'::resource_kind, 'A fill-in outline for writing a kind letter to oneself about a hard moment, using a friend''s voice.', 'Use it to give a client structure for speaking to themselves the way they would to a friend.', array['Adults']::text[], '30 minutes', 'Offer the outline when a client is harsh with themselves but warm with others. Model the friend''s voice aloud first, since many clients stall on a blank page. Read the finished letter together and ask what it was like to hear. Do not push anyone to keep a letter they find uncomfortable.', '[{"id": "f0", "type": "textarea", "label": "The hard moment in a sentence or two"}, {"id": "f1", "type": "textarea", "label": "What a good friend would notice about how I am feeling"}, {"id": "f2", "type": "textarea", "label": "What that friend would want me to know"}, {"id": "f3", "type": "textarea", "label": "One kind thing I can do for myself today"}, {"id": "f4", "type": "textarea", "label": "A line from this letter I can carry with me"}]'::jsonb, array['self-compassion', 'self-esteem', 'writing']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('three-rings-of-support-placement-map', 'Three Rings of Support Placement Map', 'worksheet'::resource_kind, 'Concentric circles where the client places the people, groups and places that support them.', 'Use it to help a client see who is around them and where support is thin.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw three rings with the client at the center: close, helpful and occasional. Let them place names without judging who belongs where. Gaps are information for you both, not failures. End by picking one person or place they might reach toward this week and what the first step looks like.', '[{"id": "f0", "type": "textarea", "label": "People in my closest ring"}, {"id": "f1", "type": "textarea", "label": "People or groups in my middle ring"}, {"id": "f2", "type": "textarea", "label": "People or places in my outer ring"}, {"id": "f3", "type": "textarea", "label": "Who I wish were closer, and why"}, {"id": "f4", "type": "textarea", "label": "One person I could reach toward this week"}, {"id": "f5", "type": "textarea", "label": "What I would say or do to reach out"}]'::jsonb, array['support', 'connection', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('conversation-rehearsal-script-page', 'Conversation Rehearsal Script Page', 'worksheet'::resource_kind, 'A page for drafting and rehearsing the opening lines of a hard but ordinary conversation.', 'Use it to help a client prepare what they want to say and how they want to say it.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a conversation the client has been putting off, such as asking a boss for a day off. Draft the first two sentences and rehearse them aloud with you. Ask what they predict the other person will say and plan one reply. Let the client change the words until they sound like themselves.', '[{"id": "f0", "type": "textarea", "label": "The conversation and who it is with"}, {"id": "f1", "type": "textarea", "label": "What I most want the other person to understand"}, {"id": "f2", "type": "textarea", "label": "My first two sentences"}, {"id": "f3", "type": "textarea", "label": "What I think they might say back"}, {"id": "f4", "type": "textarea", "label": "How I will reply"}, {"id": "f5", "type": "textarea", "label": "How I will feel if it goes differently than planned"}]'::jsonb, array['communication', 'planning', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('friend-versus-self-advice-comparison-page', 'Friend Versus Self Advice Comparison Page', 'cbt'::resource_kind, 'A page comparing the advice a client gives a friend with what they tell themselves in the same situation.', 'Use it to help a client notice when their self-talk is harsher than the advice they would give others.', array['Adults', 'Teens']::text[], '20 minutes', 'Use it when a client''s self-criticism sounds nothing like how they treat other people. Fill in the friend''s side first, because it is easier. Then ask what stops them from saying the same to themselves. Avoid arguing the point; let the contrast do the work and invite them to try the friend''s version this week.', '[{"id": "f0", "type": "textarea", "label": "The situation and what I tell myself"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend in the same spot"}, {"id": "f2", "type": "textarea", "label": "The words and tone I would use with that friend"}, {"id": "f3", "type": "textarea", "label": "What gets in the way of using that voice on myself"}, {"id": "f4", "type": "textarea", "label": "A fairer thing I can say to myself this week"}]'::jsonb, array['core CBT', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('cost-of-worrying-ledger', 'Cost of Worrying Ledger', 'cbt'::resource_kind, 'A two-sided ledger of what a client believes worry does for them and what it takes from them.', 'Use it to help a client look at worry as a habit with both costs and perceived benefits.', array['Adults']::text[], '25 minutes', 'Take the perceived benefits seriously; many clients believe worry keeps them prepared or safe. Write both columns before comparing them. Then ask what else could do that job at a lower cost. The aim is curiosity about the habit, not convincing the client to stop worrying.', '[{"id": "f0", "type": "textarea", "label": "A worry that visits me often"}, {"id": "f1", "type": "textarea", "label": "What I believe worrying does for me"}, {"id": "f2", "type": "textarea", "label": "What worrying costs me in time and energy"}, {"id": "f3", "type": "textarea", "label": "What it costs my body and sleep"}, {"id": "f4", "type": "textarea", "label": "What it costs my relationships"}, {"id": "f5", "type": "textarea", "label": "Another way to get what I want from worrying"}]'::jsonb, array['worry', 'anxiety', 'core CBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('many-possible-readings-spoke-wheel', 'Many Possible Readings Spoke Wheel', 'cbt'::resource_kind, 'A wheel with spokes for other possible explanations of an event the client read negatively.', 'Use it to help a client generate more than one reading of an ambiguous event.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose a recent event the client read in the worst light, like an unanswered text. Fill the first spoke with the explanation they landed on, then ask for at least four others, including silly ones. Ask which they could test. Warm up with a neutral example if the client resists.', '[{"id": "f0", "type": "textarea", "label": "The event and what I first assumed"}, {"id": "f1", "type": "textarea", "label": "A second explanation"}, {"id": "f2", "type": "textarea", "label": "A third explanation"}, {"id": "f3", "type": "textarea", "label": "A fourth explanation, even a silly one"}, {"id": "f4", "type": "textarea", "label": "How I could find out which is closest"}, {"id": "f5", "type": "textarea", "label": "How I feel now compared with before"}]'::jsonb, array['thinking traps', 'behavioral experiment', 'core CBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('rule-rewrite-worksheet', 'Rule Rewrite Worksheet', 'cbt'::resource_kind, 'A worksheet for turning rigid personal rules into flexible preferences.', 'Use it to help a client loosen ''must'' and ''should'' rules that keep driving distress.', array['Adults']::text[], '30 minutes', 'Collect two or three of the client''s ''always'' and ''never'' rules from the session and bring them here. Ask where each rule came from and who it serves. Rewrite one together, then have the client try living by the flexible version in a small, low-stakes way before the next visit.', '[{"id": "f0", "type": "textarea", "label": "A rule I live by (I must, I should, I never)"}, {"id": "f1", "type": "textarea", "label": "Where I learned this rule"}, {"id": "f2", "type": "textarea", "label": "What happens when I break it, or fear I will"}, {"id": "f3", "type": "textarea", "label": "What the rule costs me"}, {"id": "f4", "type": "textarea", "label": "A flexible version that still keeps what I care about"}, {"id": "f5", "type": "textarea", "label": "A small way to try the new version this week"}]'::jsonb, array['core CBT', 'rules', 'thinking traps']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('feeling-is-not-proof-separation-cards', 'Feeling Is Not Proof Separation Cards', 'cbt'::resource_kind, 'A card sequence separating how something feels from what is known about it.', 'Use it to help a client notice when a strong feeling is being treated as proof.', array['Adults', 'Teens']::text[], '15 minutes', 'Pick a moment where the client said ''I feel like a failure, so I am one'' or similar. Have them write the feeling and the conclusion on separate lines. Then list what they know for sure. Keep it light and brief; the skill is noticing the jump, which grows with repetition.', '[{"id": "f0", "type": "textarea", "label": "The feeling I had, and how strong it was"}, {"id": "f1", "type": "textarea", "label": "The conclusion my mind drew from it"}, {"id": "f2", "type": "textarea", "label": "What I know for sure about the situation"}, {"id": "f3", "type": "textarea", "label": "What I do not yet know"}, {"id": "f4", "type": "textarea", "label": "What I would conclude if I set the feeling aside"}]'::jsonb, array['thinking traps', 'core CBT', 'emotion identification']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('bus-driver-and-loud-passengers-rehearsal-log', 'Bus Driver and Loud Passengers Rehearsal Log', 'act'::resource_kind, 'A script and log for the bus metaphor, with the client driving toward a value while difficult thoughts ride along.', 'Use it to help a client practice moving toward a value without waiting for their thoughts to quiet.', array['Adults']::text[], '30 minutes', 'Run the metaphor aloud first and let the client cast their own passengers, naming the thoughts that shout loudest. Then ask where the bus is headed. Practice letting a passenger talk while the client keeps driving. Check afterward that it did not feel like ignoring or fighting the thoughts.', '[{"id": "f0", "type": "textarea", "label": "Where I want my bus to go (a value)"}, {"id": "f1", "type": "textarea", "label": "The passengers who shout at me, in their own words"}, {"id": "f2", "type": "textarea", "label": "What each passenger wants me to do"}, {"id": "f3", "type": "textarea", "label": "What I do when I let them take the wheel"}, {"id": "f4", "type": "textarea", "label": "One turn toward my value I can make this week"}, {"id": "f5", "type": "textarea", "label": "How I will thank a passenger and keep driving"}]'::jsonb, array['defusion', 'values', 'core ACT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('hands-over-face-thought-distance-practice', 'Hands Over Face Thought Distance Practice', 'act'::resource_kind, 'A short practice using the hands to feel the difference between holding a thought tight and holding it loosely.', 'Use it to give a client a felt sense of unhooking from a thought.', array['Adults']::text[], '15 minutes', 'Guide the client to press their hands over their face as if the thought were right on top of them, then lower them to the lap. Ask what changed in how much they could see. Pair it with one real thought. Skip the face-covering step with any client who may find it unsettling.', '[{"id": "f0", "type": "textarea", "label": "The thought I want to practice with"}, {"id": "f1", "type": "textarea", "label": "What I notice with my hands pressed to my face"}, {"id": "f2", "type": "textarea", "label": "What I notice when I lower them to my lap"}, {"id": "f3", "type": "textarea", "label": "What I can do with my hands free"}, {"id": "f4", "type": "textarea", "label": "When this week I could try this on my own"}]'::jsonb, array['defusion', 'core ACT', 'mindfulness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('weekly-values-direction-compass-page', 'Weekly Values Direction Compass Page', 'act'::resource_kind, 'A weekly page asking how closely the client''s actions pointed toward their chosen values.', 'Use it to help a client check direction each week without judging themselves.', array['Adults']::text[], 'Ten minutes weekly', 'Have the client name three values at the start and keep them at the top. Each week, ask what they did that pointed toward each one, however small, and where they drifted. Treat drift as information. If the client is hard on themselves, ask what a kind coach would say.', '[{"id": "f0", "type": "textarea", "label": "The three values I am steering by"}, {"id": "f1", "type": "textarea", "label": "One thing I did this week that pointed toward each"}, {"id": "f2", "type": "textarea", "label": "Where I drifted and what pulled me off course"}, {"id": "f3", "type": "textarea", "label": "What I would like next week to look like"}, {"id": "f4", "type": "textarea", "label": "One small step I choose for next week"}]'::jsonb, array['values', 'committed action', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('willing-hands-obstacle-log', 'Willing Hands Obstacle Log', 'act'::resource_kind, 'A log of the obstacles to a chosen action and the client''s willingness to carry them along.', 'Use it to help a client name what shows up when they try something that matters and make room for it.', array['Adults']::text[], '20 minutes', 'Start with one concrete action the client cares about. List what usually shows up: thoughts, feelings, urges, sensations. Ask whether they would be willing to carry those along for the sake of the action, and how much, from 0 to 10. Willingness is a choice, not a feeling, so do not push a high number.', '[{"id": "f0", "type": "textarea", "label": "The action I care about"}, {"id": "f1", "type": "textarea", "label": "The thoughts that show up when I try"}, {"id": "f2", "type": "textarea", "label": "The feelings and sensations that show up"}, {"id": "f3", "type": "textarea", "label": "How willing I am to carry them, from 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What would make it a little easier to say yes"}, {"id": "f5", "type": "textarea", "label": "What I will do and when"}]'::jsonb, array['willingness', 'committed action', 'core ACT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('sky-and-weather-journal', 'Sky and Weather Journal', 'act'::resource_kind, 'A journal built on the metaphor of the self as the sky and experiences as passing weather.', 'Use it to help a client practice noticing experiences without being defined by them.', array['Adults']::text[], 'Five minutes daily for two weeks', 'Introduce the sky and weather image in session and let the client adapt it. The daily entry asks them to name the weather and then the part of them that notices it. Some clients find this abstract at first, so give a concrete example from their own week and keep entries short.', '[{"id": "f0", "type": "textarea", "label": "Today''s weather inside me (thoughts, feelings, sensations)"}, {"id": "f1", "type": "textarea", "label": "The part of me that noticed the weather"}, {"id": "f2", "type": "textarea", "label": "What the weather wanted me to do"}, {"id": "f3", "type": "textarea", "label": "What I did instead, if anything"}, {"id": "f4", "type": "textarea", "label": "What stayed the same about me through the day"}]'::jsonb, array['self as context', 'mindfulness', 'core ACT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('camera-view-versus-story-walkthrough', 'Camera View Versus Story Walkthrough', 'dbt'::resource_kind, 'A step-by-step page for separating the facts of an event from the story and feelings around it.', 'Use it to help a client test whether an emotion fits the facts of a situation.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through one recent upset. Ask for the event described as a camera would, then the interpretations, then the emotion and its intensity. Compare the emotion with the facts and decide together whether it fits. The aim is a closer look, not talking the client out of feeling.', '[{"id": "f0", "type": "textarea", "label": "What happened, as a camera would record it"}, {"id": "f1", "type": "textarea", "label": "The interpretations and assumptions I made"}, {"id": "f2", "type": "textarea", "label": "The emotion I felt and how strong it was"}, {"id": "f3", "type": "textarea", "label": "Whether the facts fit the size of that emotion"}, {"id": "f4", "type": "textarea", "label": "What I can do that suits the facts"}]'::jsonb, array['core DBT', 'emotion regulation', 'emotion identification']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('urge-versus-opposite-step-planner', 'Urge Versus Opposite Step Planner', 'dbt'::resource_kind, 'A planner for choosing an action opposite to an emotion''s urge when the emotion does not fit the facts.', 'Use it to help a client rehearse opposite action in small, safe steps.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose an emotion where the urge is making things worse, such as withdrawing when sad. First check with the client that the emotion does not fit the facts. Then plan one small opposite step, including the body language and tone that go with it. Practice it in session if you can.', '[{"id": "f0", "type": "textarea", "label": "The emotion and its urge"}, {"id": "f1", "type": "textarea", "label": "Whether the facts fit this emotion"}, {"id": "f2", "type": "textarea", "label": "The opposite action I could take"}, {"id": "f3", "type": "textarea", "label": "How I will do it all the way, including posture and voice"}, {"id": "f4", "type": "textarea", "label": "When I will try it this week"}, {"id": "f5", "type": "textarea", "label": "How I felt after"}]'::jsonb, array['core DBT', 'emotion regulation', 'behavioral activation']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('wise-mind-pause-card', 'Wise Mind Pause Card', 'dbt'::resource_kind, 'A pocket card with a short script for pausing and checking in with wise mind before acting.', 'Use it to give a client a quick stop between a strong feeling and what they do next.', array['Adults', 'Teens']::text[], '15 minutes', 'Make the card with the client in session so the words are theirs. Practice a pause with a mild upset first. The card works best when rehearsed before it is needed, so assign a few trial runs in calm moments this week.', '[{"id": "f0", "type": "textarea", "label": "What I feel in my body when I need to pause"}, {"id": "f1", "type": "textarea", "label": "The first words I say to myself to stop"}, {"id": "f2", "type": "textarea", "label": "Where I breathe from, and for how long"}, {"id": "f3", "type": "textarea", "label": "The question I ask my wise mind"}, {"id": "f4", "type": "textarea", "label": "What I do next after the pause"}]'::jsonb, array['core DBT', 'mindfulness', 'regulation']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('please-skills-weekly-log', 'PLEASE Skills Weekly Log', 'dbt'::resource_kind, 'A seven-day log of sleep, movement, eating and substance habits that influence emotional vulnerability.', 'Use it to help a client notice how basic care shapes how easily emotions swing.', array['Adults']::text[], 'One week, five minutes daily', 'Introduce the idea that the body''s state makes emotions easier or harder to manage. The log asks about care, not performance. Review it without praise or blame, looking for one small habit the client wants to adjust. Handle the food question gently and keep it about regular care, never rules.', '[{"id": "f0", "type": "textarea", "label": "Last night''s sleep and how rested I feel"}, {"id": "f1", "type": "textarea", "label": "Whether I took care of any health needs today"}, {"id": "f2", "type": "textarea", "label": "What I ate and whether I ate regularly"}, {"id": "f3", "type": "textarea", "label": "Any substances I used"}, {"id": "f4", "type": "textarea", "label": "How much I moved my body"}, {"id": "f5", "type": "textarea", "label": "My emotional vulnerability today, from 1 to 10"}]'::jsonb, array['core DBT', 'emotion regulation', 'self-monitoring']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('dreaded-event-skills-rehearsal-sheet', 'Dreaded Event Skills Rehearsal Sheet', 'dbt'::resource_kind, 'A sheet for imagining a hard situation and rehearsing skills before it happens.', 'Use it to help a client prepare skills for a situation they already dread.', array['Adults']::text[], '30 minutes', 'Pick a real upcoming event. Ask the client to describe it in detail, name the emotions and urges likely to come up, and choose skills for each. Then have them rehearse in imagination, picturing the skill working. Stay with a mildly hard event first so rehearsal builds confidence.', '[{"id": "f0", "type": "textarea", "label": "The situation coming up and when"}, {"id": "f1", "type": "textarea", "label": "The emotions and urges I expect"}, {"id": "f2", "type": "textarea", "label": "The skills I plan to use"}, {"id": "f3", "type": "textarea", "label": "What I will say and do, step by step"}, {"id": "f4", "type": "textarea", "label": "What I will do if the plan does not go as hoped"}, {"id": "f5", "type": "textarea", "label": "How I will take care of myself afterward"}]'::jsonb, array['core DBT', 'planning', 'distress tolerance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('partner-weekly-appreciation-and-plans-meeting-guide', 'Partner Weekly Appreciation and Plans Meeting Guide', 'couples'::resource_kind, 'A guide for a weekly check-in where each partner has time to speak and be heard.', 'Use it to give a couple a short, regular space for appreciation, concerns and plans.', array['Couples']::text[], '30 minutes weekly', 'Set up the meeting in session and rehearse the order: appreciations, what went well, concerns raised softly, and plans for the coming week. Each partner takes a turn writing their part first. Remind them to keep it short and stop if either partner feels flooded, then resume later.', '[{"id": "f0", "type": "textarea", "label": "Partner A: three things I appreciated about my partner this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: three things I appreciated about my partner this week"}, {"id": "f2", "type": "textarea", "label": "Partner A: one concern, stated softly"}, {"id": "f3", "type": "textarea", "label": "Partner B: one concern, stated softly"}, {"id": "f4", "type": "textarea", "label": "What we each heard the other say"}, {"id": "f5", "type": "textarea", "label": "One thing we will each do before next week"}]'::jsonb, array['couples', 'communication', 'Gottman']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('repair-phrase-menu', 'Repair Phrase Menu', 'couples'::resource_kind, 'A menu of phrases each partner can offer to calm a tense moment and get back on track.', 'Use it to help a couple pick words they will actually say when an argument heats up.', array['Couples']::text[], '25 minutes', 'Have each partner circle phrases that would help them hear from the other, and cross out any that would sound false. Then they choose a few for themselves to offer. Rehearse one in session during a mild disagreement. The couple should write phrases in their own voices so they sound natural.', '[{"id": "f0", "type": "textarea", "label": "Partner A: phrases from my partner that would help me calm down"}, {"id": "f1", "type": "textarea", "label": "Partner B: phrases from my partner that would help me calm down"}, {"id": "f2", "type": "textarea", "label": "Partner A: phrases I can offer in a tense moment"}, {"id": "f3", "type": "textarea", "label": "Partner B: phrases I can offer in a tense moment"}, {"id": "f4", "type": "textarea", "label": "How we will signal that we want to repair"}, {"id": "f5", "type": "textarea", "label": "When we will practice this together"}]'::jsonb, array['couples', 'communication', 'conflict']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('dreams-within-conflict-interview', 'Dreams Within Conflict Interview', 'couples'::resource_kind, 'An interview for uncovering the hopes and meanings underneath a recurring disagreement.', 'Use it to help partners hear what the other cares about behind a stuck issue.', array['Couples']::text[], '40 minutes', 'Pick one recurring disagreement. One partner speaks as the other listens with curiosity and asks open questions about what the position means to them. Then switch. The goal is understanding, not agreement; stop anyone from problem-solving until both have been heard.', '[{"id": "f0", "type": "textarea", "label": "The issue we keep returning to"}, {"id": "f1", "type": "textarea", "label": "Partner A: what this issue means to me and where it comes from"}, {"id": "f2", "type": "textarea", "label": "Partner B: what this issue means to me and where it comes from"}, {"id": "f3", "type": "textarea", "label": "Partner A: a hope I have that sits underneath it"}, {"id": "f4", "type": "textarea", "label": "Partner B: a hope I have that sits underneath it"}, {"id": "f5", "type": "textarea", "label": "One thing we can honor in each other''s dream"}]'::jsonb, array['couples', 'conflict', 'Gottman']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('stress-reducing-conversation-sheet', 'Stress-Reducing Conversation Sheet', 'couples'::resource_kind, 'A sheet for taking turns to talk about outside stress while the partner listens as an ally.', 'Use it to help partners support each other about stress that comes from outside the relationship.', array['Couples']::text[], '30 minutes', 'Each partner chooses a stressor from work, family or health. The listener practices staying on the speaker''s side and holding back advice unless asked. Coach them to ask what would help most. Debrief about how it felt to be listened to and to listen.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a stress from outside our relationship"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I understood about how that feels"}, {"id": "f2", "type": "textarea", "label": "Partner B: a stress from outside our relationship"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I understood about how that feels"}, {"id": "f4", "type": "textarea", "label": "What each of us needs from the other when stressed"}, {"id": "f5", "type": "textarea", "label": "One small way we will support each other this week"}]'::jsonb, array['couples', 'support', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('bids-and-responses-tracker', 'Bids and Responses Tracker', 'couples'::resource_kind, 'A tracker where each partner notes the small bids for connection they offered and how they were met.', 'Use it to help partners notice the everyday moments where connection is offered and answered.', array['Couples']::text[], 'One week, five minutes daily', 'Explain a bid as a small reach for attention, like a comment or a gesture. Each partner logs bids they made and bids they noticed from the other. Review for patterns without scorekeeping; some couples turn this into blame, so keep the focus on noticing and appreciating.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a bid I made today and how it was met"}, {"id": "f1", "type": "textarea", "label": "Partner B: a bid I made today and how it was met"}, {"id": "f2", "type": "textarea", "label": "Partner A: a bid I noticed from my partner"}, {"id": "f3", "type": "textarea", "label": "Partner B: a bid I noticed from my partner"}, {"id": "f4", "type": "textarea", "label": "A bid I missed or wish I had answered differently"}, {"id": "f5", "type": "textarea", "label": "What we want to do more of"}]'::jsonb, array['couples', 'connection', 'Gottman']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('paper-plate-feelings-forecast-craft', 'Paper Plate Feelings Forecast Craft', 'kids'::resource_kind, 'The child builds a paper weather station and moves the arrow to show how they feel today.', 'Use it to give a child a concrete, playful way to name and share how they feel.', array['Children']::text[], '30 minutes', 'The child decorates a paper plate with weather pictures like sunny, stormy and foggy and attaches a movable arrow. Ask them to show you today''s weather and what made it that way. Send the station home and tell the parent to check it with the child once a day without fixing the feeling. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw the weather station and today''s weather"}, {"id": "f1", "type": "textarea", "label": "What made today''s weather this way"}, {"id": "f2", "type": "textarea", "label": "The weather I like best and why"}, {"id": "f3", "type": "textarea", "label": "The weather that is hardest and what helps"}, {"id": "f4", "type": "textarea", "label": "What my grown-up can do when it storms"}]'::jsonb, array['children', 'emotion identification', 'art']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('worry-monster-shoebox', 'Worry Monster Shoebox', 'kids'::resource_kind, 'The child decorates a shoebox monster and feeds it written or drawn worries before bed.', 'Use it to give a child a safe place to put worries so they can rest.', array['Children']::text[], '30 minutes', 'Provide a box with a slot and let the child give the monster a silly name and face. Worries go in as words or drawings, and a parent can read a few together the next day. Tell the parent to respond with warmth and a small plan, not reassurance alone. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry monster and give it a name"}, {"id": "f1", "type": "textarea", "label": "Worries I feed to my monster"}, {"id": "f2", "type": "textarea", "label": "What my monster looks like when it is full"}, {"id": "f3", "type": "textarea", "label": "What helps me feel calm after I feed it"}, {"id": "f4", "type": "textarea", "label": "What my grown-up does when I tell them a worry"}]'::jsonb, array['children', 'worry', 'play']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('calm-jar-build', 'Calm Jar Build', 'kids'::resource_kind, 'The child fills a jar with water, glitter and glue, and watches it settle while practicing slow breathing.', 'Use it to show a child that big feelings settle if given time and calm breaths.', array['Children']::text[], '25 minutes', 'The child shakes the jar and watches the glitter fall while breathing slowly with you. Link it to feelings: shaken is upset, settled is calm. Tell the parent to keep the jar somewhere the child can reach and to use it with them, not as a punishment. Never use it as a time-out tool.', '[{"id": "f0", "type": "textarea", "label": "Draw my calm jar"}, {"id": "f1", "type": "textarea", "label": "What my feelings look like when the glitter is swirling"}, {"id": "f2", "type": "textarea", "label": "What my body feels like when the glitter settles"}, {"id": "f3", "type": "textarea", "label": "When I could use my jar"}, {"id": "f4", "type": "textarea", "label": "Who I can use it with"}]'::jsonb, array['children', 'regulation', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('my-helper-hand', 'My Helper Hand', 'kids'::resource_kind, 'The child traces a hand and writes or draws a trusted helper on each finger.', 'Use it to help a child name the people they can turn to and what each can help with.', array['Children']::text[], '20 minutes', 'The child traces their hand and picks five people or places to turn to. Ask what each helper does best. Tell the parent that a child should have at least one adult at home on the hand and to add to it as needed. Follow reporting duties if a child discloses harm or names an unsafe person.', '[{"id": "f0", "type": "textarea", "label": "Trace my hand and draw a helper on each finger"}, {"id": "f1", "type": "textarea", "label": "The helper I talk to when I am scared"}, {"id": "f2", "type": "textarea", "label": "The helper who makes me laugh"}, {"id": "f3", "type": "textarea", "label": "What I would tell a helper if I felt sad"}, {"id": "f4", "type": "textarea", "label": "One new helper I want to add"}]'::jsonb, array['children', 'support', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('coping-cape-design', 'Coping Cape Design', 'kids'::resource_kind, 'The child designs a superhero cape covered with their own coping powers.', 'Use it to help a child see their coping skills as strengths they carry.', array['Children']::text[], '30 minutes', 'The child decorates a paper cape with symbols for skills like breathing, asking for a hug or drawing. Ask for the cape''s name and its hardest challenge. Tell the parent to wear it with the child sometimes and remind them of their powers. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my cape and name my hero"}, {"id": "f1", "type": "textarea", "label": "My coping powers"}, {"id": "f2", "type": "textarea", "label": "The monster that is hardest to beat"}, {"id": "f3", "type": "textarea", "label": "Which power I will use first"}, {"id": "f4", "type": "textarea", "label": "How my grown-up can help my powers work"}]'::jsonb, array['children', 'strengths', 'coping skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('feelings-charades-turn-cards', 'Feelings Charades Turn Cards', 'game'::resource_kind, 'Players act out feelings from cards while others guess, then share when they felt that way.', 'Use it to help a group practice reading and naming feelings in a playful setting.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Each player draws a card and acts out the feeling without words. The group guesses, and the actor shares a time they felt it if they wish. Taking a turn is optional. In the debrief, ask which feelings were hardest to show or guess and what clues helped. Keep it light and stop if someone looks overwhelmed.', '[{"id": "f0", "type": "textarea", "label": "The feeling I acted out"}, {"id": "f1", "type": "textarea", "label": "How the group guessed it"}, {"id": "f2", "type": "textarea", "label": "A time I felt this way"}, {"id": "f3", "type": "textarea", "label": "The feeling that was hardest to guess"}, {"id": "f4", "type": "textarea", "label": "What I learned about showing feelings"}]'::jsonb, array['game', 'emotion identification', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('coping-skills-bingo-night', 'Coping Skills Bingo Night', 'game'::resource_kind, 'A bingo card of coping skills where players mark each one they have tried this week.', 'Use it to encourage a group to try a wide set of coping skills and trade ideas.', array['Teens', 'Adults', 'Groups']::text[], '40 minutes', 'Make cards in advance with skills such as walking, drawing, a call to a friend or a breathing exercise. Over the week players mark skills they use. At the next session, call out skills and have players tell how it went. The first full line shares a story. Debrief on which skills they will keep.', '[{"id": "f0", "type": "textarea", "label": "The skills I marked this week"}, {"id": "f1", "type": "textarea", "label": "The skill that helped most and why"}, {"id": "f2", "type": "textarea", "label": "A skill I want to try next"}, {"id": "f3", "type": "textarea", "label": "A skill from someone else I would like to borrow"}, {"id": "f4", "type": "textarea", "label": "What I will keep doing"}]'::jsonb, array['game', 'coping skills', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('perspective-dice-game', 'Perspective Dice Game', 'game'::resource_kind, 'Players roll dice to pick a character and respond to a situation from that character''s point of view.', 'Use it to build flexibility in taking other perspectives.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Create a list of six characters, such as a friend, a teacher, a younger self, an older self, a pet and a stranger. Each player rolls, reads a short situation and answers as that character. The debrief covers what shifted and what was hard. Keep the situations mild at first.', '[{"id": "f0", "type": "textarea", "label": "The character I rolled and the situation"}, {"id": "f1", "type": "textarea", "label": "What this character would say"}, {"id": "f2", "type": "textarea", "label": "How I felt speaking as them"}, {"id": "f3", "type": "textarea", "label": "What I noticed about my own view"}, {"id": "f4", "type": "textarea", "label": "How I might use this in a real situation"}]'::jsonb, array['game', 'perspective taking', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('pretend-coins-values-bidding-game', 'Pretend Coins Values Bidding Game', 'game'::resource_kind, 'Players bid with pretend coins on values cards to find out what matters most to them.', 'Use it to help players discover which values they are willing to spend on.', array['Teens', 'Adults', 'Groups']::text[], '40 minutes', 'Give each player the same number of coins and a deck of values like family, honesty, adventure and health. Run an auction where only the highest bids win. After the auction, players explain what they bid on and what they let go. Debrief on whether their real week matches their bids.', '[{"id": "f0", "type": "textarea", "label": "The values I bid on most"}, {"id": "f1", "type": "textarea", "label": "The value I was sorry to lose"}, {"id": "f2", "type": "textarea", "label": "What my bids told me about myself"}, {"id": "f3", "type": "textarea", "label": "One value I want to spend more time on"}, {"id": "f4", "type": "textarea", "label": "One step I can take this week"}]'::jsonb, array['game', 'values', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('skill-showdown-card-game', 'Skill Showdown Card Game', 'game'::resource_kind, 'Two teams draw problem cards and race to name coping skills that fit, then explain how they would use them.', 'Use it to help players build a larger set of skills and fit them to situations.', array['Teens', 'Adults', 'Groups']::text[], '35 minutes', 'Prepare problem cards, like a long wait or an argument with a friend. Teams alternate drawing, offering a skill and explaining it. Points go for creativity and fit, not for the fastest answer. In the debrief, ask which skills seemed most realistic and which ones the group wants to practice.', '[{"id": "f0", "type": "textarea", "label": "The problem I drew"}, {"id": "f1", "type": "textarea", "label": "The skill my team picked"}, {"id": "f2", "type": "textarea", "label": "Why it fits"}, {"id": "f3", "type": "textarea", "label": "A different skill I would try"}, {"id": "f4", "type": "textarea", "label": "What I will practice before next time"}]'::jsonb, array['game', 'coping skills', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('revved-shut-down-or-workable-pacing-card', 'Revved, Shut Down or Workable Pacing Card', 'worksheet'::resource_kind, 'A card for noting when the client feels too revved, too shut down or in a workable zone.', 'Use it to help a client notice their state and choose a pace that feels workable.', array['Adults']::text[], '15 minutes', 'Draw three zones with the client and let them name their own signs for each, in the body and in thinking. Use the card at the start of sessions to set the pace. It is about noticing and pacing, not about revisiting what happened. Remind the client that 988 (call or text) is available any time they feel unsafe.', '[{"id": "f0", "type": "textarea", "label": "Signs in my body when I am too revved up"}, {"id": "f1", "type": "textarea", "label": "Signs when I am too shut down"}, {"id": "f2", "type": "textarea", "label": "Signs that I am in my workable zone"}, {"id": "f3", "type": "textarea", "label": "What helps me move toward the workable zone"}, {"id": "f4", "type": "textarea", "label": "What I need to slow down or stop in a session"}, {"id": "f5", "type": "textarea", "label": "If I ever feel unsafe, I can call or text 988 and tell someone"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('grounding-menu-by-sense', 'Grounding Menu by Sense', 'dbt'::resource_kind, 'A menu of grounding skills sorted by the five senses that the client chooses from.', 'Use it to give a client a personal set of grounding skills for hard moments.', array['Adults']::text[], '25 minutes', 'Try several grounding skills in session, such as holding something cold, naming colors or pressing feet to the floor, and have the client rate each. Keep the ones that help and cross off the rest. The client builds the menu from tools they can use anywhere. This stays in the present and does not require details of the past.', '[{"id": "f0", "type": "textarea", "label": "Sights that help me feel here and now"}, {"id": "f1", "type": "textarea", "label": "Sounds that help"}, {"id": "f2", "type": "textarea", "label": "Touch or temperature that helps"}, {"id": "f3", "type": "textarea", "label": "Smells or tastes that help"}, {"id": "f4", "type": "textarea", "label": "Movements that help"}, {"id": "f5", "type": "textarea", "label": "The three skills I will carry with me"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core DBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('safe-anchors-and-values-page', 'Safe Anchors and Values Page', 'act'::resource_kind, 'A page linking what feels steadying now with what the client wants their life to be about.', 'Use it to help a client connect small safe actions to the life they want.', array['Adults']::text[], '30 minutes', 'Start by listing people, places and routines that feel steady, then ask what the client wants to move toward. Keep the focus on the present and future. Go slowly: it is fine for the client to leave a section blank. Check in about how the page felt before the end of the session.', '[{"id": "f0", "type": "textarea", "label": "People, places and routines that feel steady"}, {"id": "f1", "type": "textarea", "label": "What I want more of in my life"}, {"id": "f2", "type": "textarea", "label": "One small thing I can do toward that this week"}, {"id": "f3", "type": "textarea", "label": "What might get in the way"}, {"id": "f4", "type": "textarea", "label": "What I can say to myself when it is hard"}, {"id": "f5", "type": "textarea", "label": "Who I can ask for support"}]'::jsonb, array['PTSD and trauma', 'values', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('five-senses-landing-game', 'Five Senses Landing Game', 'game'::resource_kind, 'A turn-taking game where players name things they can notice around the room to arrive in the present.', 'Use it to help a group practice grounding in a light, low-pressure way.', array['Adults', 'Groups']::text[], '20 minutes', 'Players take turns drawing a sense card and naming something they notice in the room. Passing is always allowed. Debrief on which prompts felt easiest and what they would use outside session. Choose a quiet, predictable room and tell players the game never asks for their stories.', '[{"id": "f0", "type": "textarea", "label": "The sense I drew and what I noticed"}, {"id": "f1", "type": "textarea", "label": "The prompt that felt easiest"}, {"id": "f2", "type": "textarea", "label": "The prompt I would use outside session"}, {"id": "f3", "type": "textarea", "label": "How my body felt after the game"}, {"id": "f4", "type": "textarea", "label": "One place I could play this on my own"}]'::jsonb, array['PTSD and trauma', 'grounding', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('safe-place-drawing-and-helper-list', 'Safe Place Drawing and Helper List', 'kids'::resource_kind, 'The child draws a place that feels safe and lists the grown-ups who help keep them safe.', 'Use it to help a child name what feels safe and who can help.', array['Children']::text[], '25 minutes', 'Invite the child to draw a real or imaginary safe place and add the helpers around it. Do not ask for details of upsetting events. Tell the parent how to keep routines steady and what to say if the child shares worries. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my safe place"}, {"id": "f1", "type": "textarea", "label": "What I see, hear and feel there"}, {"id": "f2", "type": "textarea", "label": "Who keeps me safe"}, {"id": "f3", "type": "textarea", "label": "What I do when I feel scared"}, {"id": "f4", "type": "textarea", "label": "What my grown-up can say to help"}]'::jsonb, array['PTSD and trauma', 'children', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('small-not-knowing-prediction-log', 'Small Not-Knowing Prediction Log', 'cbt'::resource_kind, 'A log for testing predictions about how bad uncertainty will feel in a small, planned way.', 'Use it to help a client try small amounts of uncertainty and compare predictions with what happened.', array['Adults']::text[], 'Two weeks, ten minutes per entry', 'Choose a small uncertain choice the client usually avoids, such as not checking a message right away. Record the prediction before and the result after. Look for the gap between the two without promising any outcome. Increase the step only when the client agrees it is time.', '[{"id": "f0", "type": "textarea", "label": "The uncertain situation I will try"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "How anxious I expect to feel, from 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "How anxious I actually felt"}, {"id": "f5", "type": "textarea", "label": "What I learned for the next try"}]'::jsonb, array['anxiety', 'behavioral experiment', 'worry']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('where-worry-lives-in-my-body-sketch', 'Where Worry Lives in My Body Sketch', 'worksheet'::resource_kind, 'An outline of a body where the client marks where anxiety is felt and what each sensation is like.', 'Use it to help a client link anxiety to body sensations and choose a response.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to color the places where they feel anxiety and describe each sensation in a few words. Notice with them how sensations come and go. Then list one thing that helps for each area. Keep the language descriptive and avoid telling them what the sensations mean.', '[{"id": "f0", "type": "textarea", "label": "Where in my body I feel anxiety"}, {"id": "f1", "type": "textarea", "label": "What those sensations feel like"}, {"id": "f2", "type": "textarea", "label": "What the sensations tell me to do"}, {"id": "f3", "type": "textarea", "label": "What I do when they show up"}, {"id": "f4", "type": "textarea", "label": "What helps each one a little"}]'::jsonb, array['anxiety', 'body', 'mindfulness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('anxiety-as-a-passenger-page', 'Anxiety as a Passenger Page', 'act'::resource_kind, 'A page for describing anxiety as a traveling companion and choosing actions while it rides along.', 'Use it to help a client act on values while anxiety is present.', array['Adults']::text[], '25 minutes', 'Ask the client to describe their anxiety as a character who travels with them. What does it say, and what does it want? Then identify one valued action to take with the character along. Keep a light, curious tone. Check that this is not being used to avoid feeling anything.', '[{"id": "f0", "type": "textarea", "label": "How I describe my anxiety as a character"}, {"id": "f1", "type": "textarea", "label": "What it says to me most"}, {"id": "f2", "type": "textarea", "label": "What it wants me to avoid"}, {"id": "f3", "type": "textarea", "label": "A valued action I want to take anyway"}, {"id": "f4", "type": "textarea", "label": "How I carry it along while I act"}, {"id": "f5", "type": "textarea", "label": "What I did and what happened"}]'::jsonb, array['anxiety', 'willingness', 'core ACT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('worry-time-card-game', 'Worry Time Card Game', 'game'::resource_kind, 'A card game where players sort worries into act now, schedule for later or let float by.', 'Use it to help players practice sorting worries by what they can do about them.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Players write real or sample worries on cards, then take turns placing them in three piles. Others can ask a question about the placement. The debrief asks what made sorting hard and which pile surprised them. Passing a card is always allowed.', '[{"id": "f0", "type": "textarea", "label": "A worry I sorted and where it went"}, {"id": "f1", "type": "textarea", "label": "What helped me decide"}, {"id": "f2", "type": "textarea", "label": "A worry that did not fit a pile"}, {"id": "f3", "type": "textarea", "label": "What I can do now about one worry"}, {"id": "f4", "type": "textarea", "label": "What I will let float by"}]'::jsonb, array['anxiety', 'worry', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('worry-dolls-build-and-tell', 'Worry Dolls Build and Tell', 'kids'::resource_kind, 'The child makes small worry dolls from craft sticks and tells each one a worry before bed.', 'Use it to give a child a playful ritual for setting worries aside at night.', array['Children']::text[], '30 minutes', 'The child decorates three or four dolls and gives each a worry to hold. Tell the parent to keep the dolls near the bed, listen to what the child shares, and not try to talk the worry away. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry dolls"}, {"id": "f1", "type": "textarea", "label": "The worry each doll holds"}, {"id": "f2", "type": "textarea", "label": "What I say to the dolls at night"}, {"id": "f3", "type": "textarea", "label": "What helps me feel safe in bed"}, {"id": "f4", "type": "textarea", "label": "What my grown-up does when I tell them"}]'::jsonb, array['anxiety', 'children', 'worry']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('doing-and-feeling-day-grid', 'Doing and Feeling Day Grid', 'cbt'::resource_kind, 'A chart linking daily activities with mood so the client can see which actions lift or lower it.', 'Use it to help a client find small activities that are connected with a better day.', array['Adults']::text[], 'One week, five minutes daily', 'Ask the client to log one activity per block and rate mood from 1 to 10. At the next session, look at the high and low points together. Start with tiny activities, like stepping outside. If hopelessness comes up, ask about safety in session and share that 988 (call or text) is open any time.', '[{"id": "f0", "type": "textarea", "label": "Time of day and what I did"}, {"id": "f1", "type": "textarea", "label": "My mood from 1 to 10"}, {"id": "f2", "type": "textarea", "label": "Whether the activity felt like pleasure or like achievement"}, {"id": "f3", "type": "textarea", "label": "What I notice across the week"}, {"id": "f4", "type": "textarea", "label": "One activity to add next week"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['depression', 'behavioral activation', 'self-monitoring']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('tiny-steps-ladder', 'Tiny Steps Ladder', 'worksheet'::resource_kind, 'A ladder of very small actions for days when energy is low.', 'Use it to help a client choose a step small enough to take even on a hard day.', array['Adults']::text[], '20 minutes', 'Build the ladder from the bottom with the client, starting with steps that take under two minutes. Let them choose what counts. When a step feels too big, split it. Review by noticing what was done rather than what was missed.', '[{"id": "f0", "type": "textarea", "label": "The smallest thing I can do on my worst day"}, {"id": "f1", "type": "textarea", "label": "A slightly bigger step"}, {"id": "f2", "type": "textarea", "label": "A step that needs a little energy"}, {"id": "f3", "type": "textarea", "label": "A step that includes another person"}, {"id": "f4", "type": "textarea", "label": "The step I will try today"}, {"id": "f5", "type": "textarea", "label": "How I will notice and give myself credit"}]'::jsonb, array['depression', 'behavioral activation', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('values-when-life-feels-flat-page', 'Values When Life Feels Flat Page', 'act'::resource_kind, 'A page for naming what matters even when interest and energy are low.', 'Use it to help a client reconnect to values when motivation is missing.', array['Adults']::text[], '30 minutes', 'Ask the client what used to matter and what they might still care about, without requiring the feeling to return first. Pick one tiny value-linked action and plan it. Do not argue with flat feelings; invite action alongside them. Ask about safety and name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Things that mattered to me before"}, {"id": "f1", "type": "textarea", "label": "Things I still care about even a little"}, {"id": "f2", "type": "textarea", "label": "One tiny action linked to a value"}, {"id": "f3", "type": "textarea", "label": "What my mood tells me about doing it"}, {"id": "f4", "type": "textarea", "label": "What I will do anyway and when"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('daily-enjoy-and-accomplish-pair-planner', 'Daily Enjoy and Accomplish Pair Planner', 'dbt'::resource_kind, 'A weekly plan with one thing for pleasure and one for mastery each day.', 'Use it to help a client balance enjoyable moments with a small sense of accomplishment.', array['Adults']::text[], '25 minutes', 'Define pleasure as enjoyable and mastery as satisfying or capable. Plan one of each for every day, keeping them small. Review what happened with curiosity. If days fall through, ask what got in the way and resize the plan.', '[{"id": "f0", "type": "textarea", "label": "Pleasant activities I could do"}, {"id": "f1", "type": "textarea", "label": "Things that give me a sense of mastery"}, {"id": "f2", "type": "textarea", "label": "This week''s plan, day by day"}, {"id": "f3", "type": "textarea", "label": "What got in the way"}, {"id": "f4", "type": "textarea", "label": "What I felt after the ones I did"}, {"id": "f5", "type": "textarea", "label": "What to adjust next week"}]'::jsonb, array['depression', 'core DBT', 'behavioral activation']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('partner-support-for-low-mood-conversation', 'Partner Support for Low Mood Conversation', 'couples'::resource_kind, 'A guide for a partner to ask how to help when the other has low mood, and for both to plan.', 'Use it to help partners talk about what support is useful and what is not.', array['Couples']::text[], '35 minutes', 'The partner with low mood describes what helps and what does not. The other listens first and asks what they can do. Together they pick one small, shared activity. Remind the partner that their role is support, not fixing, and that they need their own care too.', '[{"id": "f0", "type": "textarea", "label": "Partner with low mood: what helps me and what does not"}, {"id": "f1", "type": "textarea", "label": "Partner listening: what I heard"}, {"id": "f2", "type": "textarea", "label": "Partner listening: what I find hard"}, {"id": "f3", "type": "textarea", "label": "One small thing we can do together"}, {"id": "f4", "type": "textarea", "label": "How each of us will care for ourselves"}, {"id": "f5", "type": "textarea", "label": "When we will check in again"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('launch-pad-spot-setup', 'Launch Pad Spot Setup', 'worksheet'::resource_kind, 'A page for choosing one spot at home where everything needed for leaving the house is kept.', 'Use it to help a client reduce last-minute scrambling with one visible home base.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through leaving the house and list what is needed each time. Choose a spot near the door and decide how it will be visible and easy. Keep it simple; one system the client likes beats a complex one. Review how it went and adjust.', '[{"id": "f0", "type": "textarea", "label": "What I need when I leave the house"}, {"id": "f1", "type": "textarea", "label": "Where I will keep it all"}, {"id": "f2", "type": "textarea", "label": "How I will see it before leaving"}, {"id": "f3", "type": "textarea", "label": "What usually gets in the way"}, {"id": "f4", "type": "textarea", "label": "What I will do when something is missing"}, {"id": "f5", "type": "textarea", "label": "How I will check it this week"}]'::jsonb, array['ADHD', 'routines', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-doubling-craft-hour-plan', 'Body Doubling Craft Hour Plan', 'kids'::resource_kind, 'A parent and child plan for working side by side on a task, with a timer and a sticker chart.', 'Use it to help a child start a task with company and short breaks.', array['Children']::text[], '25 minutes', 'The child and parent decorate a timer card and pick a task. The parent works nearby on something else, and both take short breaks. Tell the parent to stay calm, notice effort and skip lectures. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw our work spot"}, {"id": "f1", "type": "textarea", "label": "The task I will start"}, {"id": "f2", "type": "textarea", "label": "How long I will work before a break"}, {"id": "f3", "type": "textarea", "label": "What I will do on my break"}, {"id": "f4", "type": "textarea", "label": "What my grown-up does while I work"}]'::jsonb, array['ADHD', 'children', 'routines']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('time-sense-estimation-game', 'Time Sense Estimation Game', 'game'::resource_kind, 'Players guess how long tasks take, then time them and compare.', 'Use it to build a feel for how long things take.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Each player guesses how long a small task will take, then does it with a timer. Compare guesses with real times and talk about patterns without scoring against anyone. In debrief, ask how they will use this when planning a day. Keep tasks simple.', '[{"id": "f0", "type": "textarea", "label": "The task and my guess"}, {"id": "f1", "type": "textarea", "label": "How long it actually took"}, {"id": "f2", "type": "textarea", "label": "Was I faster or slower than I guessed"}, {"id": "f3", "type": "textarea", "label": "What this tells me about planning"}, {"id": "f4", "type": "textarea", "label": "One real task I will time this week"}]'::jsonb, array['ADHD', 'time management', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('task-start-barrier-log', 'Task Start Barrier Log', 'cbt'::resource_kind, 'A log of what gets in the way of starting a task and what small trick helps.', 'Use it to help a client find the specific barrier at the start of a task.', array['Adults']::text[], 'One week, five minutes daily', 'Ask the client to log tasks they delayed and what they noticed in the moment before starting. Then try one start trick, like a two-minute timer. Look at the barriers together. Avoid labeling delay as laziness.', '[{"id": "f0", "type": "textarea", "label": "The task I put off"}, {"id": "f1", "type": "textarea", "label": "What I thought or felt before starting"}, {"id": "f2", "type": "textarea", "label": "What got in the way"}, {"id": "f3", "type": "textarea", "label": "A trick I tried to start"}, {"id": "f4", "type": "textarea", "label": "What happened after I started"}, {"id": "f5", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['ADHD', 'planning', 'self-monitoring']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('household-load-reset-meeting-sheet', 'Household Load Reset Meeting Sheet', 'couples'::resource_kind, 'A sheet for partners to list shared tasks and decide who takes what with reminders that work.', 'Use it to help partners divide tasks in a way that fits how each of them works.', array['Couples']::text[], '40 minutes', 'List household tasks and each partner''s preferences. Agree on reminders that are not nagging, such as a shared calendar. Keep blame out by discussing systems, not character. Review after one week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I can take and how I remember them"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I can take and how I remember them"}, {"id": "f2", "type": "textarea", "label": "Tasks that need a new system"}, {"id": "f3", "type": "textarea", "label": "How we will remind without nagging"}, {"id": "f4", "type": "textarea", "label": "How we will thank each other"}, {"id": "f5", "type": "textarea", "label": "When we will review"}]'::jsonb, array['ADHD', 'couples', 'routines']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('urge-rise-and-fade-timeline-log', 'Urge Rise and Fade Timeline Log', 'cbt'::resource_kind, 'A log for tracking an urge from start to peak to fade, with notes on what was noticed.', 'Use it to help a client see that urges rise and pass without acting.', array['Adults']::text[], 'One week, five minutes per urge', 'Ask the client to record the time, the cue and the intensity as they ride the urge. Notice together how it changed. Do not promise it will end in a set time. If substance use occurred, treat it as information, not failure.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what set off the urge"}, {"id": "f1", "type": "textarea", "label": "Strength of the urge from 0 to 10 at the start"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body and thoughts"}, {"id": "f3", "type": "textarea", "label": "What I did while it rose"}, {"id": "f4", "type": "textarea", "label": "Strength at the end"}, {"id": "f5", "type": "textarea", "label": "What I learned about urges"}]'::jsonb, array['addiction', 'urges', 'self-monitoring']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('values-behind-substance-use-page', 'Values Behind Substance Use Page', 'act'::resource_kind, 'A page for exploring what substance use gives the client and what it takes from their values.', 'Use it to help a client look at substance use in light of what matters to them.', array['Adults']::text[], '30 minutes', 'Approach with curiosity and no judgment. Ask what substance use does for them and how it fits their values. Pick one small action toward a value that does not involve using. Support their choices and keep their goals central.', '[{"id": "f0", "type": "textarea", "label": "What substance use gives me"}, {"id": "f1", "type": "textarea", "label": "What it takes from what I care about"}, {"id": "f2", "type": "textarea", "label": "What I value in my life"}, {"id": "f3", "type": "textarea", "label": "One action toward a value without using"}, {"id": "f4", "type": "textarea", "label": "Who I want to be around"}, {"id": "f5", "type": "textarea", "label": "What I will do when an urge comes"}]'::jsonb, array['addiction', 'values', 'urges']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('urge-surfing-and-distraction-plan', 'Urge Surfing and Distraction Plan', 'dbt'::resource_kind, 'A plan combining mindful awareness of urges with distraction and self-soothing options.', 'Use it to give a client a tool set for moments when urges are strong.', array['Adults']::text[], '30 minutes', 'List high-risk times and choose a mix of skills: mindful noticing, distraction and self-soothing. Rehearse one in session. Include people to contact. If the client is in crisis, name 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "High-risk times and places for urges"}, {"id": "f1", "type": "textarea", "label": "Mindful steps I can take"}, {"id": "f2", "type": "textarea", "label": "Distractions that work for me"}, {"id": "f3", "type": "textarea", "label": "Self-soothing that works"}, {"id": "f4", "type": "textarea", "label": "People I can contact"}, {"id": "f5", "type": "textarea", "label": "If I am in crisis, I can call or text 988"}]'::jsonb, array['addiction', 'urges', 'core DBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('recovery-support-week-planner', 'Recovery Support Week Planner', 'worksheet'::resource_kind, 'A weekly planner placing supports, routines and enjoyable activities in the client''s days.', 'Use it to help a client build a week that supports their goals around substance use.', array['Adults']::text[], '30 minutes', 'Fill the week with supports such as meetings, calls, exercise and fun. Mark the riskiest hours and add support there. Be realistic; a full plan the client keeps is better than a perfect one. Review each week.', '[{"id": "f0", "type": "textarea", "label": "My goals around substance use"}, {"id": "f1", "type": "textarea", "label": "Supports I will use this week"}, {"id": "f2", "type": "textarea", "label": "Routines I will keep"}, {"id": "f3", "type": "textarea", "label": "Enjoyable things I will schedule"}, {"id": "f4", "type": "textarea", "label": "The riskiest times and my plan"}, {"id": "f5", "type": "textarea", "label": "Who I will tell about the plan"}]'::jsonb, array['addiction', 'planning', 'support']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('family-conversations-about-substance-use-guide', 'Family Conversations About Substance Use Guide', 'couples'::resource_kind, 'A guide for a partner or family member and the client to talk about substance use, impact and support.', 'Use it to help partners speak openly about substance use without blame.', array['Couples']::text[], '40 minutes', 'Set ground rules: speak for yourself, no labels, and pause when heated. Each partner shares what they notice, how it affects them and what they hope for. Close with one agreement. Offer separate support for the partner too.', '[{"id": "f0", "type": "textarea", "label": "Partner using: what I want my partner to know"}, {"id": "f1", "type": "textarea", "label": "Partner using: how I see my goals"}, {"id": "f2", "type": "textarea", "label": "Partner listening: what I notice and how it affects me"}, {"id": "f3", "type": "textarea", "label": "Partner listening: what I hope for"}, {"id": "f4", "type": "textarea", "label": "What each of us needs"}, {"id": "f5", "type": "textarea", "label": "One agreement for this week"}]'::jsonb, array['addiction', 'couples', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('anger-trigger-and-thought-log', 'Anger Trigger and Thought Log', 'cbt'::resource_kind, 'A log linking triggers, hot thoughts, body signs and actions during anger.', 'Use it to help a client spot the thoughts that fuel anger and the point to pause.', array['Adults']::text[], 'One week, ten minutes per entry', 'Fill in an entry in session for a recent event. Ask what the client told themselves just before the anger peaked. Then write a calmer version of the thought. Do not label anger as bad; it is information. Keep safety in mind and check on any risk to others.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "The thoughts that came up"}, {"id": "f2", "type": "textarea", "label": "Where I felt anger in my body"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "A calmer thought I could try"}, {"id": "f5", "type": "textarea", "label": "What I will do differently next time"}]'::jsonb, array['anger management', 'thinking traps', 'emotion regulation']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('cool-down-skills-ladder', 'Cool Down Skills Ladder', 'dbt'::resource_kind, 'A ladder of skills from quick body resets to longer calming steps for anger.', 'Use it to give a client a set of ways to bring anger down by degrees.', array['Adults', 'Teens']::text[], '25 minutes', 'Build the ladder from fast skills like cold water or paced breathing up to longer ones like a walk. Try two in session and rate their effect. The client picks which belongs at each rung. Add a step for returning to the conversation later.', '[{"id": "f0", "type": "textarea", "label": "Skills that work in seconds"}, {"id": "f1", "type": "textarea", "label": "Skills that need a few minutes"}, {"id": "f2", "type": "textarea", "label": "Skills for a longer cool down"}, {"id": "f3", "type": "textarea", "label": "What I say to leave a tense moment"}, {"id": "f4", "type": "textarea", "label": "How I come back to the conversation"}, {"id": "f5", "type": "textarea", "label": "Which skill I will practice first"}]'::jsonb, array['anger management', 'core DBT', 'regulation']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('heat-levels-paper-volcano-build', 'Heat Levels Paper Volcano Build', 'kids'::resource_kind, 'The child builds a paper volcano and marks the warning signs before it erupts, with cool-down tools.', 'Use it to help a child notice early anger signals and practice cooling down.', array['Children']::text[], '30 minutes', 'Build a volcano with levels and ask the child what their body does at each. Add calm-down tools at the lower levels. Tell the parent to praise early cool-downs and talk about repair afterward, not punishment. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my volcano"}, {"id": "f1", "type": "textarea", "label": "What happens in my body as it heats up"}, {"id": "f2", "type": "textarea", "label": "My warning signs"}, {"id": "f3", "type": "textarea", "label": "What cools me down"}, {"id": "f4", "type": "textarea", "label": "What my grown-up does to help"}]'::jsonb, array['anger management', 'children', 'regulation']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('anger-thermometer-role-play-game', 'Anger Thermometer Role Play Game', 'game'::resource_kind, 'Players draw scenarios, rate the heat and pick a skill to bring the temperature down.', 'Use it to help players practice choosing skills at different anger levels.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Create scenario cards and a thermometer. Players rate the heat, choose a skill and act out the response with a partner. Others suggest alternatives. Debrief on what worked and why. Keep scenarios mild and allow passing.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew and my heat rating"}, {"id": "f1", "type": "textarea", "label": "The skill I picked"}, {"id": "f2", "type": "textarea", "label": "How it went in the role play"}, {"id": "f3", "type": "textarea", "label": "What someone else suggested"}, {"id": "f4", "type": "textarea", "label": "What I will try in real life"}]'::jsonb, array['anger management', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('pause-signal-and-come-back-pact', 'Pause Signal and Come-Back Pact', 'couples'::resource_kind, 'An agreement partners make for taking a break during conflict and when to come back.', 'Use it to help partners pause heated conversations and return respectfully.', array['Couples']::text[], '30 minutes', 'Partners agree on a signal, how long the break lasts and what each does during it. The one who calls it must also return. Practice calling it in session. Make sure the break is not a way of leaving the other behind. If there is any fear of harm, speak with each partner separately.', '[{"id": "f0", "type": "textarea", "label": "Our signal for a break"}, {"id": "f1", "type": "textarea", "label": "How long we will take"}, {"id": "f2", "type": "textarea", "label": "What I will do during the break"}, {"id": "f3", "type": "textarea", "label": "How I will return to the conversation"}, {"id": "f4", "type": "textarea", "label": "What I need from my partner during a break"}, {"id": "f5", "type": "textarea", "label": "When we will practice"}]'::jsonb, array['anger management', 'couples', 'conflict']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-practice-rungs-planner', 'Intrusive Thought Practice Rungs Planner', 'cbt'::resource_kind, 'A ladder of steps from easier to harder situations with notes on staying without rituals.', 'Use it to plan gradual practice with situations that set off intrusive thoughts.', array['Adults']::text[], 'Full session', 'Build the ladder with the client, ranking steps by distress. Agree on which rituals to skip at each step and how to stay with the feeling. Start at a low rung and practice together. Move up only when the client is ready. This is a planning page that supports your own clinical judgment.', '[{"id": "f0", "type": "textarea", "label": "Situations that set off my intrusive thoughts"}, {"id": "f1", "type": "textarea", "label": "Ranking from easiest to hardest"}, {"id": "f2", "type": "textarea", "label": "The first step I will try"}, {"id": "f3", "type": "textarea", "label": "The ritual I will skip"}, {"id": "f4", "type": "textarea", "label": "How I will stay with the feeling"}, {"id": "f5", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['OCD', 'exposure', 'avoidance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('thoughts-are-not-instructions-defusion-page', 'Thoughts Are Not Instructions Defusion Page', 'act'::resource_kind, 'A page practicing the difference between having an intrusive thought and acting on it.', 'Use it to help a client notice thoughts as thoughts and choose actions by values.', array['Adults']::text[], '25 minutes', 'Have the client write an intrusive thought as ''I am having the thought that...''. Say it in a silly voice and ask what changes. Then pick a value-based action. Be careful not to use defusion as another ritual; check how it felt.', '[{"id": "f0", "type": "textarea", "label": "An intrusive thought I notice"}, {"id": "f1", "type": "textarea", "label": "I am having the thought that..."}, {"id": "f2", "type": "textarea", "label": "What changes when I say it that way"}, {"id": "f3", "type": "textarea", "label": "What the thought wants me to do"}, {"id": "f4", "type": "textarea", "label": "What I choose to do for my values"}, {"id": "f5", "type": "textarea", "label": "What helped me not act on it"}]'::jsonb, array['OCD', 'defusion', 'core ACT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('ritual-time-tracker', 'Ritual Time Tracker', 'worksheet'::resource_kind, 'A tracker for noticing how much time rituals take and what they cost.', 'Use it to help a client see the time and energy that rituals use.', array['Adults']::text[], 'One week, five minutes daily', 'Ask the client to log rituals without judgment: when, how long and what came before. Review for patterns and discuss what they are giving up. Keep it descriptive so shame does not grow.', '[{"id": "f0", "type": "textarea", "label": "Time and what set off the ritual"}, {"id": "f1", "type": "textarea", "label": "What I did and for how long"}, {"id": "f2", "type": "textarea", "label": "What I felt before and after"}, {"id": "f3", "type": "textarea", "label": "What I missed because of it"}, {"id": "f4", "type": "textarea", "label": "What I would rather be doing"}, {"id": "f5", "type": "textarea", "label": "One small step I will try"}]'::jsonb, array['OCD', 'self-monitoring', 'routines']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('worry-bully-talk-back-cards', 'Worry Bully Talk-Back Cards', 'kids'::resource_kind, 'The child draws the worry bully and writes brave talk-back lines on cards.', 'Use it to help a child separate themselves from a bossy worry voice.', array['Children']::text[], '30 minutes', 'The child draws the bully and gives it a silly name. Together write talk-back lines like ''I do not have to do what you say.'' Tell the parent to avoid giving reassurance on repeat and to cheer on brave choices. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry bully"}, {"id": "f1", "type": "textarea", "label": "What the bully tells me to do"}, {"id": "f2", "type": "textarea", "label": "My brave talk-back lines"}, {"id": "f3", "type": "textarea", "label": "One time I did not listen"}, {"id": "f4", "type": "textarea", "label": "How my grown-up can cheer me on"}]'::jsonb, array['OCD', 'children', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('roll-and-leave-it-unchecked-dice-game', 'Roll and Leave It Unchecked Dice Game', 'game'::resource_kind, 'Players roll for small uncertain tasks and try them without checking or fixing.', 'Use it to help players practice tolerating small uncertainty together.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Create a die of mild tasks such as leaving a drawer open or writing without rereading. Players take turns and report how they felt. Do not use this with anyone for whom a task feels too hard. Debrief on what was surprising.', '[{"id": "f0", "type": "textarea", "label": "The task I rolled"}, {"id": "f1", "type": "textarea", "label": "What I felt before I did it"}, {"id": "f2", "type": "textarea", "label": "What I felt afterward"}, {"id": "f3", "type": "textarea", "label": "What I noticed about uncertainty"}, {"id": "f4", "type": "textarea", "label": "A task I will try this week"}]'::jsonb, array['OCD', 'game', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('panic-sensation-experiment-plan', 'Panic Sensation Experiment Plan', 'cbt'::resource_kind, 'A plan to induce a safe harmless sensation in session and notice what happens.', 'Use it to help a client test fears about body sensations.', array['Adults']::text[], 'Full session', 'Pick a sensation such as spinning in a chair or breathing quickly. Ask for predictions before and results after. Stay with the client throughout. Check for medical concerns with the client before using any exercise that changes breathing.', '[{"id": "f0", "type": "textarea", "label": "The sensation I will try"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "What I felt during it"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I learned about sensations"}, {"id": "f5", "type": "textarea", "label": "What I will practice next"}]'::jsonb, array['panic attacks', 'exposure', 'behavioral experiment']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('minute-by-minute-surge-replay-page', 'Minute by Minute Surge Replay Page', 'worksheet'::resource_kind, 'A page for describing a panic wave from rise to fall, with what was done.', 'Use it to help a client see how panic rises and passes.', array['Adults']::text[], '15 minutes', 'Ask the client to describe a recent wave minute by minute. Mark the peak and the fade. Ask what they did and what might help next time. Do not say what the sensations mean beyond describing them.', '[{"id": "f0", "type": "textarea", "label": "Where I was when it began"}, {"id": "f1", "type": "textarea", "label": "The first sensations I noticed"}, {"id": "f2", "type": "textarea", "label": "The peak and what it felt like"}, {"id": "f3", "type": "textarea", "label": "How it faded"}, {"id": "f4", "type": "textarea", "label": "What I did"}, {"id": "f5", "type": "textarea", "label": "What I would try next time"}]'::jsonb, array['panic attacks', 'body', 'self-monitoring']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('slow-exhale-and-cold-pack-pocket-card', 'Slow Exhale and Cold Pack Pocket Card', 'dbt'::resource_kind, 'A card with paced breathing and cold-water steps for sudden surges of arousal.', 'Use it to give a client quick skills for the body in a panic wave.', array['Adults']::text[], '20 minutes', 'Practice a paced exhale and holding a cold pack in session. Ask the client which works best. Write steps on a card. Check for medical issues before using temperature skills.', '[{"id": "f0", "type": "textarea", "label": "Paced breathing steps that work for me"}, {"id": "f1", "type": "textarea", "label": "Temperature skills I can use"}, {"id": "f2", "type": "textarea", "label": "Where I will keep my card"}, {"id": "f3", "type": "textarea", "label": "How I rate the skills from 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What I say to myself during a wave"}]'::jsonb, array['panic attacks', 'core DBT', 'distress tolerance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('making-room-for-the-wave-page', 'Making Room for the Wave Page', 'act'::resource_kind, 'A page for dropping the fight with panic sensations and choosing a values action.', 'Use it to help a client let the wave pass while doing what matters.', array['Adults']::text[], '25 minutes', 'Explain that struggling can make the wave feel stronger. Ask the client to name the sensations and let them be there. Then pick a value-led action in the next hour. Check how they felt about it.', '[{"id": "f0", "type": "textarea", "label": "The sensations I fight"}, {"id": "f1", "type": "textarea", "label": "What fighting costs me"}, {"id": "f2", "type": "textarea", "label": "What it is like to let them be there"}, {"id": "f3", "type": "textarea", "label": "A place I want to go despite panic"}, {"id": "f4", "type": "textarea", "label": "What I will do when the next wave comes"}]'::jsonb, array['panic attacks', 'willingness', 'core ACT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('panic-balloon-breathing-craft', 'Panic Balloon Breathing Craft', 'kids'::resource_kind, 'The child decorates a balloon and practices slow breathing as it inflates and deflates.', 'Use it to teach a child slow breathing in a playful way.', array['Children']::text[], '20 minutes', 'The child watches the balloon grow and shrink as they breathe in and out slowly. Ask how their body feels. Tell the parent to practice with the child when calm, not just during panic. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my balloon"}, {"id": "f1", "type": "textarea", "label": "How my body feels when I am scared"}, {"id": "f2", "type": "textarea", "label": "How I breathe with the balloon"}, {"id": "f3", "type": "textarea", "label": "How I feel after"}, {"id": "f4", "type": "textarea", "label": "When I will use it"}]'::jsonb, array['panic attacks', 'children', 'regulation']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('parent-routine-builder', 'Parent Routine Builder', 'worksheet'::resource_kind, 'A page for building morning and bedtime routines with the child''s input.', 'Use it to help a parent set up predictable routines the child helps shape.', array['Adults']::text[], '30 minutes', 'Walk through the morning and bedtime with the parent. List steps, then ask the child to add ideas. Use visual charts for young children. Start with one routine and expand later. Keep tone warm, not rigid.', '[{"id": "f0", "type": "textarea", "label": "Our morning steps"}, {"id": "f1", "type": "textarea", "label": "Our bedtime steps"}, {"id": "f2", "type": "textarea", "label": "What my child wants to add"}, {"id": "f3", "type": "textarea", "label": "Where we get stuck"}, {"id": "f4", "type": "textarea", "label": "A visual cue I will use"}, {"id": "f5", "type": "textarea", "label": "How I will praise effort"}]'::jsonb, array['parenting', 'routines', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('praise-jar-family-craft', 'Praise Jar Family Craft', 'kids'::resource_kind, 'A jar the family fills with notes of things that went well.', 'Use it to help a family notice and name effort.', array['Children']::text[], '25 minutes', 'The child decorates a jar and the parent writes or draws notes of effort. Read a few notes at dinner or bedtime. Tell the parent to praise specific actions. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw our jar"}, {"id": "f1", "type": "textarea", "label": "A note about something I did well"}, {"id": "f2", "type": "textarea", "label": "A note about my grown-up"}, {"id": "f3", "type": "textarea", "label": "How I felt reading notes"}, {"id": "f4", "type": "textarea", "label": "When we will read them"}]'::jsonb, array['parenting', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('calm-response-role-play-game', 'Calm Response Role Play Game', 'game'::resource_kind, 'Parents take turns drawing scenarios and practicing a calm response.', 'Use it to help parents rehearse calm replies to tough moments.', array['Adults', 'Groups']::text[], '35 minutes', 'Make cards of common moments like refusing homework. Parents take turns playing the child and the parent. Others give feedback on what worked. Debrief on what made calm hard and what helps. Allow passing.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "My calm response"}, {"id": "f2", "type": "textarea", "label": "What the group said helped"}, {"id": "f3", "type": "textarea", "label": "What was hardest"}, {"id": "f4", "type": "textarea", "label": "What I will try at home"}]'::jsonb, array['parenting', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('co-parent-alignment-conversation-sheet', 'Co-Parent Alignment Conversation Sheet', 'couples'::resource_kind, 'A sheet for co-parents to talk about rules, roles and support.', 'Use it to help co-parents get on the same page and support each other.', array['Couples']::text[], '40 minutes', 'Each parent lists the top three rules they care about. Compare lists and discuss where they differ with curiosity. Agree on a short plan and how to back each other up in front of the child. Raise only issues that are safe to discuss together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the three rules I care about most"}, {"id": "f1", "type": "textarea", "label": "Partner B: the three rules I care about most"}, {"id": "f2", "type": "textarea", "label": "Where we differ"}, {"id": "f3", "type": "textarea", "label": "What we agree on"}, {"id": "f4", "type": "textarea", "label": "How we back each other up"}, {"id": "f5", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['parenting', 'couples', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('validation-phrases-for-parents-practice', 'Validation Phrases for Parents Practice', 'dbt'::resource_kind, 'A practice sheet for validating a child''s feelings before problem solving.', 'Use it to help parents practice validating phrases.', array['Adults']::text[], '25 minutes', 'Share a short list of validating phrases and practice with real examples. Distinguish validation from agreeing or giving in. Have the parent role-play with you, then try it once at home.', '[{"id": "f0", "type": "textarea", "label": "A time my child was upset"}, {"id": "f1", "type": "textarea", "label": "What I usually say"}, {"id": "f2", "type": "textarea", "label": "A validating phrase I could use"}, {"id": "f3", "type": "textarea", "label": "What I want to do after validating"}, {"id": "f4", "type": "textarea", "label": "How it went when I tried"}]'::jsonb, array['parenting', 'core DBT', 'family']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('night-shift-sharing-and-rest-block-planner', 'Night Shift Sharing and Rest Block Planner', 'worksheet'::resource_kind, 'A planner for dividing nights and daytime rest among people who can help.', 'Use it to help a new parent find protected rest and support.', array['Adults', 'Couples']::text[], '30 minutes', 'List who can help and when, including partners, relatives and friends. Plan a block of rest for the client every day. Ask about what feels hard to ask for. If the client talks about thoughts of harming themselves or the baby, address it right away in session and share that 988 (call or text) is there any time.', '[{"id": "f0", "type": "textarea", "label": "People who can help"}, {"id": "f1", "type": "textarea", "label": "Times I need rest most"}, {"id": "f2", "type": "textarea", "label": "A protected rest block"}, {"id": "f3", "type": "textarea", "label": "What I find hard to ask for"}, {"id": "f4", "type": "textarea", "label": "How I will ask"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'support', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('mom-guilt-thought-review', 'Mom Guilt Thought Review', 'cbt'::resource_kind, 'A review of guilt thoughts about parenting with a fairer look at standards.', 'Use it to help a parent look at guilt-driven thoughts about parenting.', array['Adults']::text[], '25 minutes', 'Collect the ''should'' thoughts the parent has about feeding, sleep or time. Ask where the standard comes from and how a friend would judge it. Write a fairer thought. Avoid arguing the parent out of feelings.', '[{"id": "f0", "type": "textarea", "label": "The guilt thought"}, {"id": "f1", "type": "textarea", "label": "Where the standard comes from"}, {"id": "f2", "type": "textarea", "label": "What I would tell a friend"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "What I will do for myself"}]'::jsonb, array['perinatal and postpartum', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('new-baby-roles-and-appreciation-talk', 'New Baby Roles and Appreciation Talk', 'couples'::resource_kind, 'A conversation guide for two partners adjusting to a new baby.', 'Use it to help partners share the load and notice each other''s efforts.', array['Couples']::text[], '40 minutes', 'Each partner lists what they are carrying and what they appreciate in the other. Then plan one change. Keep it kind. Encourage them to name needs rather than keep score.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I carry"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I carry"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I appreciate"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I appreciate"}, {"id": "f4", "type": "textarea", "label": "One change we will try"}, {"id": "f5", "type": "textarea", "label": "When we will talk again"}]'::jsonb, array['perinatal and postpartum', 'couples', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('values-in-the-fog-of-new-parenthood-page', 'Values in the Fog of New Parenthood Page', 'act'::resource_kind, 'A page for naming what matters now and tiny actions that fit.', 'Use it to help a parent connect with values when time and energy are scarce.', array['Adults']::text[], '25 minutes', 'Ask the parent what kind of parent and person they want to be. Choose one tiny action per day. Accept that some days will be survival. Check in on feelings and ask about safety when needed, mentioning 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "What I value as a parent"}, {"id": "f1", "type": "textarea", "label": "What I value as a person"}, {"id": "f2", "type": "textarea", "label": "A tiny action for today"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "How I will be kind to myself"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('soothe-myself-between-feedings-plan', 'Soothe Myself Between Feedings Plan', 'dbt'::resource_kind, 'A plan of self-soothing through the senses for short breaks.', 'Use it to help a parent calm themselves in small windows.', array['Adults']::text[], '20 minutes', 'List sensory comforts that take under five minutes. Choose one for each of the five senses. Practice one in session. Ask where the parent can keep a small comfort kit.', '[{"id": "f0", "type": "textarea", "label": "Something to see that soothes me"}, {"id": "f1", "type": "textarea", "label": "Something to hear"}, {"id": "f2", "type": "textarea", "label": "Something to touch"}, {"id": "f3", "type": "textarea", "label": "Something to smell or taste"}, {"id": "f4", "type": "textarea", "label": "Where I will keep it"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'distress tolerance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('core-belief-evidence-journal', 'Core Belief Evidence Journal', 'cbt'::resource_kind, 'A journal collecting evidence that supports a kinder belief about oneself.', 'Use it to help a client build a fairer view of themselves over time.', array['Adults']::text[], 'Five minutes daily', 'Choose one harsh belief and a more balanced one. Each day the client writes a piece of evidence for the balanced belief. Be patient; beliefs shift slowly. Review entries and celebrate small shifts.', '[{"id": "f0", "type": "textarea", "label": "The harsh belief"}, {"id": "f1", "type": "textarea", "label": "A kinder belief I want to test"}, {"id": "f2", "type": "textarea", "label": "Evidence today for the kinder belief"}, {"id": "f3", "type": "textarea", "label": "How much I believe it from 0 to 100"}, {"id": "f4", "type": "textarea", "label": "What I will look for tomorrow"}]'::jsonb, array['self-esteem', 'core CBT', 'thinking traps']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('self-worth-is-not-a-report-card-page', 'Self-Worth Is Not a Report Card Page', 'act'::resource_kind, 'A page separating worth from performance and linking to values.', 'Use it to help a client act on values without needing a perfect score.', array['Adults']::text[], '25 minutes', 'Ask where the client learned to measure worth by results. Name a value and an action that matters regardless of outcome. Keep the tone gentle.', '[{"id": "f0", "type": "textarea", "label": "How I measure my worth"}, {"id": "f1", "type": "textarea", "label": "Where I learned that"}, {"id": "f2", "type": "textarea", "label": "What I value that is not a result"}, {"id": "f3", "type": "textarea", "label": "An action I can take no matter the outcome"}, {"id": "f4", "type": "textarea", "label": "What I say to myself when I fall short"}]'::jsonb, array['self-esteem', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('i-am-great-at-poster', 'I Am Great At Poster', 'kids'::resource_kind, 'The child makes a poster of strengths with the help of a parent''s words.', 'Use it to help a child see what they do well.', array['Children']::text[], '30 minutes', 'The child writes or draws strengths on a poster and the parent adds a note. Display it at home. Tell the parent to praise effort and character. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my poster"}, {"id": "f1", "type": "textarea", "label": "Three things I am good at"}, {"id": "f2", "type": "textarea", "label": "Something kind I did"}, {"id": "f3", "type": "textarea", "label": "What my grown-up says about me"}, {"id": "f4", "type": "textarea", "label": "Where I will hang it"}]'::jsonb, array['self-esteem', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('strength-spotting-circle-game', 'Strength Spotting Circle Game', 'game'::resource_kind, 'Players spot strengths in each other with cards and give appreciations.', 'Use it to help a group notice and accept strengths.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Each player draws a strength card and offers a real appreciation to another. The receiver says thank you. Debrief on how it felt to give and to receive. Make passing available.', '[{"id": "f0", "type": "textarea", "label": "The strength I spotted"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "What I heard about myself"}, {"id": "f3", "type": "textarea", "label": "How it felt to receive"}, {"id": "f4", "type": "textarea", "label": "One strength I will own"}]'::jsonb, array['self-esteem', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('inner-critic-interview-page', 'Inner Critic Interview Page', 'worksheet'::resource_kind, 'An interview with the inner critic: what it says, why and what it is afraid of.', 'Use it to help a client understand the intent behind the critic.', array['Adults']::text[], '25 minutes', 'Ask the client to give the critic a name and ask what it wants. Often it is protecting. Then ask what a gentler coach would say. Do not try to silence it.', '[{"id": "f0", "type": "textarea", "label": "The name of my critic"}, {"id": "f1", "type": "textarea", "label": "What it says most"}, {"id": "f2", "type": "textarea", "label": "What it is trying to protect me from"}, {"id": "f3", "type": "textarea", "label": "What it costs me"}, {"id": "f4", "type": "textarea", "label": "What a kind coach would say"}]'::jsonb, array['self-esteem', 'self-compassion', 'thinking traps']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('social-prediction-test-sheet', 'Social Prediction Test Sheet', 'cbt'::resource_kind, 'A sheet for predicting how a social situation will go, then testing it.', 'Use it to help a client check predictions against what happens.', array['Adults']::text[], 'Full session', 'Pick a small social task. Record predictions, safety behaviors and outcomes. Ask what the client noticed about others. Keep tasks gradual and agreed on.', '[{"id": "f0", "type": "textarea", "label": "The social situation"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen"}, {"id": "f2", "type": "textarea", "label": "Safety behaviors I will drop"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I noticed about other people"}, {"id": "f5", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('connection-value-single-step-page', 'Connection Value Single Step Page', 'act'::resource_kind, 'A page for choosing connection as a value and one step despite fear.', 'Use it to help a client move toward connection while anxious.', array['Adults']::text[], '25 minutes', 'Ask what connection means to the client. Pick a step like greeting someone. Name the thoughts that will come and decide to carry them. Review what happened.', '[{"id": "f0", "type": "textarea", "label": "What connection means to me"}, {"id": "f1", "type": "textarea", "label": "A small social step"}, {"id": "f2", "type": "textarea", "label": "Thoughts that will come"}, {"id": "f3", "type": "textarea", "label": "Feelings I will carry"}, {"id": "f4", "type": "textarea", "label": "What I did"}, {"id": "f5", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('opener-and-follow-up-pairing-game', 'Opener and Follow-Up Pairing Game', 'game'::resource_kind, 'Players practice starters and follow-up questions with cards.', 'Use it to help players try conversation starters in a low-stakes game.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Make cards with openers and follow-ups. Players pair up and practice for two minutes, then swap. Debrief on what felt natural. Passing is fine.', '[{"id": "f0", "type": "textarea", "label": "The opener I drew"}, {"id": "f1", "type": "textarea", "label": "How the chat went"}, {"id": "f2", "type": "textarea", "label": "A follow-up I liked"}, {"id": "f3", "type": "textarea", "label": "What was hard"}, {"id": "f4", "type": "textarea", "label": "Where I will use it"}]'::jsonb, array['social anxiety', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('attention-inside-and-out-experiment-page', 'Attention Inside and Out Experiment Page', 'worksheet'::resource_kind, 'A page comparing focusing on oneself with focusing on the other person.', 'Use it to help a client notice how self-focus affects anxiety in conversation.', array['Adults']::text[], '25 minutes', 'Run a short conversation in session twice, once focusing inward and once outward. Rate anxiety and connection each time. Discuss what changed. Repeat outside session.', '[{"id": "f0", "type": "textarea", "label": "How I felt focusing on myself"}, {"id": "f1", "type": "textarea", "label": "How I felt focusing on the other person"}, {"id": "f2", "type": "textarea", "label": "What I noticed about the conversation"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "Where I will practice"}]'::jsonb, array['social anxiety', 'attention', 'behavioral experiment']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('interpersonal-confidence-script-card', 'Interpersonal Confidence Script Card', 'dbt'::resource_kind, 'A card with short scripts for asking, saying no and joining a group.', 'Use it to give a client words to use in social moments.', array['Adults', 'Teens']::text[], '30 minutes', 'Draft scripts with the client using DEAR MAN steps. Practice in role play. Keep scripts short and in their own voice. Give feedback on tone.', '[{"id": "f0", "type": "textarea", "label": "A situation where I want to speak up"}, {"id": "f1", "type": "textarea", "label": "What I want to say"}, {"id": "f2", "type": "textarea", "label": "How I will say it"}, {"id": "f3", "type": "textarea", "label": "My tone and posture"}, {"id": "f4", "type": "textarea", "label": "How it went in practice"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'DEAR MAN']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('grief-wave-notes', 'Grief Wave Notes', 'worksheet'::resource_kind, 'A page for noticing grief waves, what set them off and what helped.', 'Use it to help a client see grief as something that comes and goes.', array['Adults']::text[], '20 minutes', 'Ask the client to record when waves come and what comforts. Normalize that grief has no schedule. Do not push toward closure. Ask about safety if the client feels hopeless and share that 988 (call or text) is open any time.', '[{"id": "f0", "type": "textarea", "label": "When a wave came"}, {"id": "f1", "type": "textarea", "label": "What set it off"}, {"id": "f2", "type": "textarea", "label": "What it felt like"}, {"id": "f3", "type": "textarea", "label": "What helped"}, {"id": "f4", "type": "textarea", "label": "Who I reached out to"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['grief and loss', 'support', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-i-loved-and-how-i-honor-it-page', 'What I Loved and How I Honor It Page', 'act'::resource_kind, 'A page linking what the client loved about the person with ways to honor it.', 'Use it to help a client carry values and love forward after a loss.', array['Adults']::text[], '30 minutes', 'Ask what the person valued and what the client values about them. Choose one small act that honors that. Let the client set the pace and allow tears.', '[{"id": "f0", "type": "textarea", "label": "What I loved about them"}, {"id": "f1", "type": "textarea", "label": "What they valued"}, {"id": "f2", "type": "textarea", "label": "A way to honor that"}, {"id": "f3", "type": "textarea", "label": "What makes it hard"}, {"id": "f4", "type": "textarea", "label": "What I will do and when"}]'::jsonb, array['grief and loss', 'values', 'connection']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('keepsake-box-for-a-missed-person-or-pet', 'Keepsake Box for a Missed Person or Pet', 'kids'::resource_kind, 'The child decorates a box and fills it with drawings and keepsakes of someone they miss.', 'Use it to give a child a safe way to remember a person or pet.', array['Children']::text[], '30 minutes', 'The child decorates a box and picks items. Let them talk or stay quiet. Tell the parent that questions and repeated sadness are common and to answer honestly in simple words. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my memory box"}, {"id": "f1", "type": "textarea", "label": "What I put in it"}, {"id": "f2", "type": "textarea", "label": "A good memory"}, {"id": "f3", "type": "textarea", "label": "How I feel today"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('two-ways-of-mourning-partner-talk-guide', 'Two Ways of Mourning Partner Talk Guide', 'couples'::resource_kind, 'A guide for partners who grieve in different ways to share and support.', 'Use it to help partners understand each other''s different grieving.', array['Couples']::text[], '40 minutes', 'Each partner describes how they grieve and what they need. Listen without comparing. Choose one shared ritual and one space for solo time.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve"}, {"id": "f2", "type": "textarea", "label": "What I need from you"}, {"id": "f3", "type": "textarea", "label": "What I find hard to see in you"}, {"id": "f4", "type": "textarea", "label": "A shared ritual"}, {"id": "f5", "type": "textarea", "label": "A way to give each other space"}]'::jsonb, array['grief and loss', 'couples', 'support']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('story-stones-remembering-game', 'Story Stones Remembering Game', 'game'::resource_kind, 'Players choose stones with pictures and share a memory or feeling.', 'Use it to help a group remember and share at their own pace.', array['Adults', 'Groups']::text[], '30 minutes', 'Paint simple pictures on stones. Players draw one and share a memory if they wish. Others listen without fixing. Debrief on what it was like.', '[{"id": "f0", "type": "textarea", "label": "The stone I drew"}, {"id": "f1", "type": "textarea", "label": "The memory it brought"}, {"id": "f2", "type": "textarea", "label": "How I felt sharing"}, {"id": "f3", "type": "textarea", "label": "What I heard from others"}, {"id": "f4", "type": "textarea", "label": "What I will take with me"}]'::jsonb, array['grief and loss', 'game', 'group']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('softened-startup-practice-sheet', 'Softened Startup Practice Sheet', 'couples'::resource_kind, 'A sheet for rewording complaints into gentle requests.', 'Use it to help partners begin tough talks with less blame.', array['Couples']::text[], '30 minutes', 'Take a complaint and rewrite it as ''I feel... about... and I need...''. Practice aloud. Give feedback on tone. Note the difference in how it lands.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my complaint as I would usually say it"}, {"id": "f1", "type": "textarea", "label": "Partner A: my softened version"}, {"id": "f2", "type": "textarea", "label": "Partner B: my complaint as I would usually say it"}, {"id": "f3", "type": "textarea", "label": "Partner B: my softened version"}, {"id": "f4", "type": "textarea", "label": "How each version felt to hear"}]'::jsonb, array['relationship issues', 'couples', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('dear-man-relationship-request-page', 'DEAR MAN Relationship Request Page', 'dbt'::resource_kind, 'A page for planning a clear, respectful request in a relationship.', 'Use it to help a client ask for what they need with skill.', array['Adults']::text[], '30 minutes', 'Walk through each step: Describe, Express, Assert, Reinforce, Mindful, Appear confident, Negotiate. Role play the request. Plan for different responses.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Describe the facts"}, {"id": "f2", "type": "textarea", "label": "Express my feelings"}, {"id": "f3", "type": "textarea", "label": "Assert what I ask"}, {"id": "f4", "type": "textarea", "label": "What I offer in return"}, {"id": "f5", "type": "textarea", "label": "How I will respond if they say no"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('guess-about-their-thoughts-ask-first-page', 'Guess About Their Thoughts Ask-First Page', 'cbt'::resource_kind, 'A page for catching assumptions about a partner''s thoughts and checking them.', 'Use it to help a client check guesses about what others think.', array['Adults']::text[], '20 minutes', 'List the assumption and how it affected behavior. Brainstorm other explanations. Plan a way to ask. Practice the question in session.', '[{"id": "f0", "type": "textarea", "label": "What I assumed"}, {"id": "f1", "type": "textarea", "label": "How it changed what I did"}, {"id": "f2", "type": "textarea", "label": "Other explanations"}, {"id": "f3", "type": "textarea", "label": "A question I can ask"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('needs-and-wants-trading-game', 'Needs and Wants Trading Game', 'game'::resource_kind, 'Players trade cards of needs and wants and discuss what they are willing to give.', 'Use it to help players talk about needs and compromise playfully.', array['Adults', 'Groups']::text[], '30 minutes', 'Make cards for needs like quiet time or affection. Players trade with partners and explain choices. Debrief on what was hard to give or ask. Keep it kind.', '[{"id": "f0", "type": "textarea", "label": "The cards I traded"}, {"id": "f1", "type": "textarea", "label": "What I asked for"}, {"id": "f2", "type": "textarea", "label": "What I gave"}, {"id": "f3", "type": "textarea", "label": "What was hard"}, {"id": "f4", "type": "textarea", "label": "What I will try in real life"}]'::jsonb, array['relationship issues', 'game', 'communication']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('closeness-and-conflict-patterns-strip', 'Closeness and Conflict Patterns Strip', 'worksheet'::resource_kind, 'A timeline of how the client has acted in past relationships and what they want next.', 'Use it to help a client see patterns and choose different steps.', array['Adults']::text[], '35 minutes', 'Ask for a few moments, not full histories. Notice patterns in how they handle closeness and conflict. Focus on what they want now and one new step.', '[{"id": "f0", "type": "textarea", "label": "Moments that stand out"}, {"id": "f1", "type": "textarea", "label": "Patterns I notice"}, {"id": "f2", "type": "textarea", "label": "What I did well"}, {"id": "f3", "type": "textarea", "label": "What I want to do differently"}, {"id": "f4", "type": "textarea", "label": "One new step"}]'::jsonb, array['relationship issues', 'patterns', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('today-s-safe-people-and-places-plan-page', 'Today''s Safe People and Places Plan Page', 'worksheet'::resource_kind, 'A page naming safe people, places and steps without recounting any events.', 'Use it to help a client build a current-day plan for safety and support.', array['Adults', 'Teens']::text[], '30 minutes', 'Focus on the present: who is safe, where, and what to do when feeling unsafe. Never ask for details of the past. Check reporting duties if the client is a minor. Share that 988 (call or text) is available any time, and RAINN at 800-656-4673.', '[{"id": "f0", "type": "textarea", "label": "People I trust"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safe"}, {"id": "f2", "type": "textarea", "label": "What I do when I feel unsafe"}, {"id": "f3", "type": "textarea", "label": "Who I can call"}, {"id": "f4", "type": "textarea", "label": "Steps for a hard day"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('grounding-and-pacing-skills-menu', 'Grounding and Pacing Skills Menu', 'dbt'::resource_kind, 'A menu of grounding and pacing skills to use before and after session.', 'Use it to help a client slow down and stay present.', array['Adults']::text[], '25 minutes', 'Try several skills in session and let the client rate them. Agree on a pace and a stop signal. Nothing here asks for details of what happened. Check in at the end.', '[{"id": "f0", "type": "textarea", "label": "Skills that ground me"}, {"id": "f1", "type": "textarea", "label": "Skills that help me slow down"}, {"id": "f2", "type": "textarea", "label": "My stop signal"}, {"id": "f3", "type": "textarea", "label": "What I do after a session"}, {"id": "f4", "type": "textarea", "label": "Who I can contact"}]'::jsonb, array['sexual abuse', 'grounding', 'core DBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('reclaiming-choices-values-page', 'Reclaiming Choices Values Page', 'act'::resource_kind, 'A page about choices the client can make now that fit their values.', 'Use it to help a client notice choice and agency in daily life.', array['Adults']::text[], '30 minutes', 'Invite the client to list small daily choices that are theirs. Link to values. Go slowly and let them skip anything. Never ask about past events.', '[{"id": "f0", "type": "textarea", "label": "Small choices that are mine"}, {"id": "f1", "type": "textarea", "label": "What I value"}, {"id": "f2", "type": "textarea", "label": "A choice I want to make this week"}, {"id": "f3", "type": "textarea", "label": "What supports me"}, {"id": "f4", "type": "textarea", "label": "What I will do if it feels hard"}]'::jsonb, array['sexual abuse', 'values', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-safety-rules-drawing', 'Body Safety Rules Drawing', 'kids'::resource_kind, 'The child draws the people and rules that keep their body safe and who to tell.', 'Use it to help a child learn safety rules and trusted adults.', array['Children']::text[], '25 minutes', 'Use simple, age-appropriate language: my body belongs to me, and I can always tell a trusted adult. Do not ask for details. Tell the parent how to respond calmly if a child shares. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw me and my safe grown-ups"}, {"id": "f1", "type": "textarea", "label": "Who I can tell"}, {"id": "f2", "type": "textarea", "label": "The rule about my body"}, {"id": "f3", "type": "textarea", "label": "What I do if someone makes me feel unsafe"}, {"id": "f4", "type": "textarea", "label": "What my grown-up says"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fair-thoughts-about-blame-cards', 'Fair Thoughts About Blame Cards', 'cbt'::resource_kind, 'Cards for gently looking at self-blame thoughts and finding fairer ones.', 'Use it to help a client meet self-blame thoughts with kindness.', array['Adults']::text[], '25 minutes', 'Work only with thoughts, not events. Ask the client what they would tell a friend. Write a fairer thought and practice reading it. Skip if the client feels unsteady. Share that 988 (call or text) is available.', '[{"id": "f0", "type": "textarea", "label": "A blame thought that visits me"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f2", "type": "textarea", "label": "A fairer thought"}, {"id": "f3", "type": "textarea", "label": "How I feel reading it"}, {"id": "f4", "type": "textarea", "label": "Who supports me"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['sexual abuse', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('tipp-skills-practice-log', 'TIPP Skills Practice Log', 'dbt'::resource_kind, 'A log for practicing temperature, intense exercise, paced breathing and relaxation.', 'Use it to help a client try body-based skills for fast relief.', array['Adults']::text[], 'One week, ten minutes per entry', 'Teach each skill and rate it in session. Ask the client to log use and effect. Check for health issues before temperature or exercise skills.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Which TIPP skill I used"}, {"id": "f2", "type": "textarea", "label": "Distress before"}, {"id": "f3", "type": "textarea", "label": "Distress after"}, {"id": "f4", "type": "textarea", "label": "What I would change"}]'::jsonb, array['coping skills', 'distress tolerance', 'core DBT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('room-hunt-for-everyday-calm-tools', 'Room Hunt for Everyday Calm Tools', 'game'::resource_kind, 'Players hunt for items and places that support coping skills and share how they use them.', 'Use it to help players find coping tools around them.', array['Teens', 'Adults', 'Groups']::text[], '35 minutes', 'Make a list like something soft, something that smells nice, a quiet spot. Players find them and explain use. Debrief on which they will use.', '[{"id": "f0", "type": "textarea", "label": "What I found"}, {"id": "f1", "type": "textarea", "label": "How I could use it"}, {"id": "f2", "type": "textarea", "label": "What surprised me"}, {"id": "f3", "type": "textarea", "label": "What I will keep"}, {"id": "f4", "type": "textarea", "label": "Where I will use it"}]'::jsonb, array['coping skills', 'game', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('decorate-and-fill-my-calm-tool-box', 'Decorate and Fill My Calm Tool Box', 'kids'::resource_kind, 'The child decorates a box and fills it with coping tools they pick.', 'Use it to help a child build a personal set of coping tools.', array['Children']::text[], '30 minutes', 'The child decorates a box and adds drawings or small items like a stress ball. Practice using each. Tell the parent to keep it handy. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my toolbox"}, {"id": "f1", "type": "textarea", "label": "Tools I put in"}, {"id": "f2", "type": "textarea", "label": "Which tool I use first"}, {"id": "f3", "type": "textarea", "label": "When I will use it"}, {"id": "f4", "type": "textarea", "label": "How my grown-up helps"}]'::jsonb, array['coping skills', 'children', 'skills']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('hard-moment-to-skill-pairing-chart', 'Hard Moment to Skill Pairing Chart', 'worksheet'::resource_kind, 'A chart matching feelings and situations with coping skills.', 'Use it to help a client match skills to what they face.', array['Adults', 'Teens']::text[], '25 minutes', 'List common difficult moments and brainstorm skills. Rate each match from 0 to 10. Revise after trying them.', '[{"id": "f0", "type": "textarea", "label": "A hard situation"}, {"id": "f1", "type": "textarea", "label": "Skills that might fit"}, {"id": "f2", "type": "textarea", "label": "My rating of each"}, {"id": "f3", "type": "textarea", "label": "The one I will try"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['coping skills', 'skills', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('willingness-to-feel-practice-page', 'Willingness to Feel Practice Page', 'act'::resource_kind, 'A page practicing making room for a feeling for a short time.', 'Use it to help a client build willingness to feel without escape.', array['Adults']::text[], '20 minutes', 'Choose a mild feeling and have the client stay with it for a minute, noticing sensations. Rate willingness. Debrief gently.', '[{"id": "f0", "type": "textarea", "label": "The feeling I picked"}, {"id": "f1", "type": "textarea", "label": "Where I notice it"}, {"id": "f2", "type": "textarea", "label": "How willing I was"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "How I might use this"}]'::jsonb, array['coping skills', 'willingness', 'core ACT']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('feared-situations-rung-ranking-page', 'Feared Situations Rung Ranking Page', 'cbt'::resource_kind, 'A ladder of feared situations ranked from easiest to hardest.', 'Use it to help a client plan gradual steps toward a feared situation.', array['Adults']::text[], 'Full session', 'List situations and rate fear for each. Pick a first step that is challenging but doable. Plan how to stay in it. Agree on pacing together.', '[{"id": "f0", "type": "textarea", "label": "The fear I want to work on"}, {"id": "f1", "type": "textarea", "label": "Situations ranked by fear"}, {"id": "f2", "type": "textarea", "label": "My first step"}, {"id": "f3", "type": "textarea", "label": "How long I will stay"}, {"id": "f4", "type": "textarea", "label": "What I notice after"}]'::jsonb, array['phobias', 'exposure', 'avoidance']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('sticker-ladder-of-brave-small-steps', 'Sticker Ladder of Brave Small Steps', 'kids'::resource_kind, 'The child decorates a ladder with small brave steps and stickers.', 'Use it to help a child take small steps toward something scary.', array['Children']::text[], '25 minutes', 'The child draws a ladder with steps from easy to hard. Add stickers after each step. Tell the parent to cheer effort and never force a step. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my ladder"}, {"id": "f1", "type": "textarea", "label": "My first step"}, {"id": "f2", "type": "textarea", "label": "Who helps me"}, {"id": "f3", "type": "textarea", "label": "How I feel after a step"}, {"id": "f4", "type": "textarea", "label": "What I get to do after"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fear-facing-board-game', 'Fear Facing Board Game', 'game'::resource_kind, 'Players move along a board and take on small fear-facing challenges.', 'Use it to help a group try small exposures with support.', array['Teens', 'Adults', 'Groups']::text[], '40 minutes', 'Create a board with challenge squares at mild levels. Players choose challenges and cheer each other. Debrief on what it was like. Always allow a pass.', '[{"id": "f0", "type": "textarea", "label": "The challenge I took"}, {"id": "f1", "type": "textarea", "label": "How scared I felt"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "The next challenge"}]'::jsonb, array['phobias', 'game', 'exposure']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-i-skip-because-of-fear-map', 'What I Skip Because of Fear Map', 'worksheet'::resource_kind, 'A map of things the client avoids because of a fear and what it costs.', 'Use it to help a client see how avoidance shapes daily life.', array['Adults']::text[], '25 minutes', 'List places and activities avoided. Ask what each costs. Choose one to work toward. Keep non-judgmental.', '[{"id": "f0", "type": "textarea", "label": "Things I avoid"}, {"id": "f1", "type": "textarea", "label": "What I miss out on"}, {"id": "f2", "type": "textarea", "label": "What I fear will happen"}, {"id": "f3", "type": "textarea", "label": "One thing I want back"}, {"id": "f4", "type": "textarea", "label": "A first step"}]'::jsonb, array['phobias', 'avoidance', 'planning']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('fear-and-values-crossroads-page', 'Fear and Values Crossroads Page', 'act'::resource_kind, 'A page for choosing values-led action when fear points elsewhere.', 'Use it to help a client choose a valued direction with fear present.', array['Adults']::text[], '25 minutes', 'Draw a crossroads with fear on one path and values on the other. Discuss what each gives. Choose a step and plan to carry the fear.', '[{"id": "f0", "type": "textarea", "label": "What fear tells me to do"}, {"id": "f1", "type": "textarea", "label": "What my values point to"}, {"id": "f2", "type": "textarea", "label": "The cost of each path"}, {"id": "f3", "type": "textarea", "label": "The step I will take"}, {"id": "f4", "type": "textarea", "label": "What I will carry with me"}]'::jsonb, array['phobias', 'values', 'willingness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-talk-thought-record', 'Body Talk Thought Record', 'cbt'::resource_kind, 'A thought record for noticing critical thoughts about the body and shifting them.', 'Use it to help a client catch critical body thoughts and find a fairer view.', array['Adults']::text[], '25 minutes', 'Ask the client to notice when body thoughts spike and what was happening. Write a fairer thought focusing on what the body does. Avoid discussing size, shape or appearance rules.', '[{"id": "f0", "type": "textarea", "label": "Where I was when the thought came"}, {"id": "f1", "type": "textarea", "label": "The thought"}, {"id": "f2", "type": "textarea", "label": "How it made me feel"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "What my body did for me today"}]'::jsonb, array['body image', 'thinking traps', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-as-a-home-values-page', 'Body as a Home Values Page', 'act'::resource_kind, 'A page about caring for and appreciating the body as the home where life happens.', 'Use it to help a client act on values rather than appearance.', array['Adults']::text[], '25 minutes', 'Ask what the client''s body lets them do. Link to values and plan one caring act. Keep focus on function and care.', '[{"id": "f0", "type": "textarea", "label": "What my body lets me do"}, {"id": "f1", "type": "textarea", "label": "What I value"}, {"id": "f2", "type": "textarea", "label": "One caring act this week"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "How I will notice"}]'::jsonb, array['body image', 'values', 'self-compassion']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('body-judgment-letting-go-practice', 'Body Judgment Letting-Go Practice', 'dbt'::resource_kind, 'A mindfulness practice for noticing body judgments without acting on them.', 'Use it to help a client observe judgments and return to the present.', array['Adults']::text[], '20 minutes', 'Teach non-judgmental stance. Have the client notice a judgment, label it ''judgment'' and return to the senses. Practice in session.', '[{"id": "f0", "type": "textarea", "label": "A judgment I noticed"}, {"id": "f1", "type": "textarea", "label": "How I labeled it"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my senses"}, {"id": "f3", "type": "textarea", "label": "How I returned"}, {"id": "f4", "type": "textarea", "label": "When I will practice"}]'::jsonb, array['body image', 'core DBT', 'mindfulness']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('appreciation-for-who-we-are-exchange', 'Appreciation for Who We Are Exchange', 'couples'::resource_kind, 'Partners trade appreciation about character and shared moments, not looks.', 'Use it to help partners value each other beyond appearance.', array['Couples']::text[], '25 minutes', 'Each writes appreciations about qualities and actions. Read aloud and receive. Debrief on what it felt like. Keep appearance out.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I appreciate about my partner"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I appreciate about my partner"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear"}, {"id": "f3", "type": "textarea", "label": "A moment I treasure"}, {"id": "f4", "type": "textarea", "label": "How we will keep it up"}]'::jsonb, array['body image', 'couples', 'connection']::text[], '2026-10-27T15:00:00+00:00'::timestamptz),
  ('what-my-body-does-collage', 'What My Body Does Collage', 'kids'::resource_kind, 'The child makes a collage of all the things their body does and loves.', 'Use it to help a child value what their body can do.', array['Children']::text[], '30 minutes', 'The child cuts pictures or draws activities like running, hugging and laughing. Tell the parent to talk about what bodies do, not how they look. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my collage"}, {"id": "f1", "type": "textarea", "label": "Things my body does"}, {"id": "f2", "type": "textarea", "label": "My favorite"}, {"id": "f3", "type": "textarea", "label": "How my body helps me"}, {"id": "f4", "type": "textarea", "label": "What my grown-up says"}]'::jsonb, array['body image', 'children', 'strengths']::text[], '2026-10-27T15:00:00+00:00'::timestamptz)
